programs.sol:
"""Detect punctuation following a sentence boundary.

Opening brackets and quotes respond strongly after a full stop, less after
other punctuation. Leading-space tokens respond more than attached ones.
Parentheses after abbreviations are weaker than at ordinary sentence ends.
Nonbreaking spaces, A/a/i, and lowercase words also respond after dots.
Unmodeled lexical variation is left at zero.
"""
import re

READS = ()
# punctuation family, full-stop response amplitude, background level
PUNCTUATION = (
    ('(（', 3.7, -0.02), ('[【', 2.5, -0.04), ('{', 1.9, -0.10),
    ('"', 2.5, -0.06), ('“「', 2.45, 0.03), ("'‘", 1.8, -0.03),
    ('„', 1.55, 0.25), ('«»」', 2.0, 0.0), ('-', 1.4, -0.03),
    ('–—', 1.9, 0.0), ('…', 2.5, -0.03), ('\\', 1.25, -0.02),
    ('*', 1.0, -0.02), ('$#§%+/^`', 1.0, 0.0), ('\xa0', 1.45, 0.0),
)
BOUNDARY = re.compile(r'([.。?!！？:：;,，；])([\'"’”»）)\]}]*)(\s*)$')
ABBREVIATIONS = frozenset('al eq eqs fig figs ref refs pp p dr mr mrs ms '
                          'etc inc ltd co jr st'.split())


def response(s, prev, before):
    q = s.lstrip()
    m = BOUNDARY.search(prev)
    mark = m[1] if m else ''
    strength = 0.0
    if mark in ('.', '。'):
        strength = 1.0
        if prev == '.':
            word = before.strip()
            if word.lower() in ABBREVIATIONS:
                strength = 0.6
            elif word.isdigit():
                strength = 0.75
            elif len(word) == 1:
                strength = 0.85
    elif mark in ('?', '!', '？', '！'):
        strength = 0.65
    elif mark in (':', '：', ';', '；'):
        strength = 0.25
    elif mark in (',', '，'):
        strength = 0.08
    elif prev.rstrip().endswith((')', ']', '}', '）', '”', '"')):
        strength = 0.18
    quoted_closer = prev.rstrip()[:-1].endswith((')', '"', '”'))
    if m and mark not in ('.', '。') and (m[2] or quoted_closer):
        strength *= 0.25
    if m and '\n' in m[3]:
        strength *= 0.5
    if q in ('：“', ':“'):
        return 0.65
    if len(q) > 1 and q[0] in '.。' and q[1] in '(（["“”\\-^':
        value = 1.8 if q[1] in '([（' else 0.55
        if q.startswith('。（'):
            value = 2.3
        elif q.startswith('。“'):
            value = 1.35
        return value * (0.2 if '\n' in s else 1.0)
    if s.isspace():
        if '\xa0' not in s:
            return 0.12 * strength if s == ' ' else 0.0
        q = '\xa0'
    if not q:
        return 0.0
    if s.startswith(' ') and q.isalpha() and mark == '.':
        if q in ('A', 'a', 'i'):
            return 0.65 * strength
        return 0.11 * strength if q.islower() else 0.0
    if any(c.isalnum() for c in q):
        return 0.0
    key = '…' if q.startswith('...') else q[0]
    family = next((row for row in PUNCTUATION if key in row[0]), None)
    if family is None:
        return 0.0
    _, amplitude, base = family
    # A quote fused with a closer or code separator is not an opening quote.
    if key in "\"'" and any(c in q[1:] for c in '),;/\\'):
        amplitude *= 0.25
    value = base + amplitude * strength
    if not s.startswith(' ') and key not in ('\xa0', '„'):
        value *= 0.35
    if key in '(（' and prev.isspace():
        value = 0.35
    if q.startswith('(\\'):
        value *= 0.3
    return value * (0.15 if '\n' in s else 1.0)


def step(carry, prefix, upstream):
    doc, s = prefix.document_ids[-1], prefix.token_strings[-1]
    old = carry if carry is not None and carry[0] == doc else (doc, '', '')
    return (doc, s, old[1]), float(response(s, old[1], old[2]))

"""An adjacent-separator / phrase-head interaction, not a general comma detector.

After a comma, auxiliaries and prepositions respond positively, whereas listing
or emphasis markers and capitalized words respond negatively. Smaller gains
apply after other separators. Coefficients are rounded training calibrations.
Only two tokens in the same document are consulted; ordinary contexts give zero.
"""
READS = ()

COPULAS = set('is are was were'.split())
PERFECT_AUX = set('has have had'.split())
MODALS = set('will would can could may might must should'.split())
PREPOSITIONS = {
    'of': 1.75, 'to': 1.57, 'in': 1.32, 'for': 1.19,
    'by': 1.12, 'at': 1.02, 'on': 1.08, 'with': 0.91,
    'as': 0.87, 'from': 0.57, 'after': 0.66, 'before': 1.00,
    'without': 0.82, 'within': 1.25, 'into': 1.10,
}
CLAUSE_WORDS = {
    'that': 1.33, 'who': 0.48, 'when': 0.69, 'how': 0.80,
    'what': 0.70, 'why': 0.64, 'if': 0.57, 'while': 0.54,
    'because': 0.57, 'since': 0.61, 'which': -0.18,
}


def word_response(s):
    w = s.strip()
    if w in COPULAS:
        return 2.40
    if w in PERFECT_AUX or w in MODALS or w in ('does', 'did'):
        return 1.95
    if w in ('be', 'being', 'do', 'shall', 'am'):
        return 1.10
    if w in PREPOSITIONS:
        return PREPOSITIONS[w]
    if w in CLAUSE_WORDS:
        return CLAUSE_WORDS[w]
    if w in ('especially', 'particularly', '尤其是', '特别是',
             '特別是', '特に'):
        return -1.60
    if w in ('including', '包括', '比如'):
        return -1.10
    if w in ('如', '例如', '以及'):
        return -0.65
    if w == '是' or w.startswith('是一') or w in ('为', '為'):
        return 1.00
    if w in ('said', 'says', 'told'):
        return 1.12
    if s.startswith(' '):
        if w in ('or', 'however', 'such', 'one', 'even'):
            return -0.25
        if w in ('a', 'an', 'the', 'but', 'so', 'not'):
            return -0.07
        if w in ('and', 'then', 'let'):
            return 0.0
        if w.isalpha() and len(w) > 1 and w[0].isupper():
            return -0.18
        if w.isascii() and w.isalpha():
            if w.endswith('ed'):
                return 0.42
            if w.endswith('ing'):
                return 0.14
            return 0.10 if len(w) > 1 else -0.05
        if w in ('(', '()'):
            return 0.85
    if w in ('+', '-'):
        return 0.40
    return 0.0


def step(carry, prefix, upstream):
    if len(prefix.token_ids) < 2 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, 0.0
    s, previous = prefix.token_strings[-1], prefix.token_strings[-2]
    p = previous.rstrip()
    gain = 0.0
    if any(c in p for c in ',，、') and not any(c.isalnum() for c in p):
        gain = 0.35 if s.isascii() and s.isalpha() else 1.0
    elif p.strip() in ('-', '--', '–', '—'):
        gain = 0.40
    elif p.endswith(('(', '（')):
        gain = 0.30
        if s.strip() in ('including', '包括', '尤其是', '特别是', '特に'):
            gain = 0.80
    elif p.endswith((')', '）')):
        gain = 0.10
    elif p.endswith(';'):
        gain = 0.23
    elif p.endswith(':'):
        gain = 0.13
    elif previous.isspace() and '\n' not in previous:
        gain = 0.08
    return None, float(gain * word_response(s))

programs.haiku:
"""layers.0.mlp.down_proj:2178 -- "the verb that resumes the main clause after a comma".

What it does: the component is silent almost everywhere. It fires on the first word
after a comma, when that word is one that carries the main clause on from an inserted
phrase or appositive, as in "Jeanette Lawson, [is] bedridden" or "The fort, possibly
known as Fort Henry, [was] built in ...". The strongest case is a finite verb
(is/was/are/has/will ...), then a preposition or connective that restarts the clause
("to", "of", "in", "that"), and it is negative after list-introducers such as
"including", "especially", "particularly", which open a list rather than resume a clause.
Words after a comma that are none of these get 0.

The program is a word-class rule, with no table of token ids. The graded values
are rough class means fitted to the component's activations on training text.
"""

READS = ()

# Finite verbs: copulas, auxiliaries and modals, which take the main clause's verb slot.
VERBS = {"is", "are", "was", "were", "has", "have", "had", "will", "would", "can",
         "could", "may", "might", "must", "shall", "should", "do", "does", "did", "be"}
# Prepositions and connectives that continue the sentence after an inserted phrase.
CLAUSE_PREPS = {"to", "of", "in", "on", "for", "by", "at", "with", "from", "that"}
SUBORDINATORS = {"as", "if", "when", "since", "after", "before", "while", "because", "who"}
# Words that open a list or an apposition, rather than resuming the main clause.
LISTERS = {"including", "especially", "particularly", "such", "Inc"}


def step(carry, prefix, upstream):
    # Only the first word after a comma, inside one document, can fire.
    if len(prefix) < 2 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return None, 0.0
    if not prefix.token_strings[-2].endswith(","):
        return None, 0.0
    word = prefix.token_strings[-1].strip()
    if word in VERBS:
        return None, 2.2
    if word in CLAUSE_PREPS:
        return None, 1.3
    if word in SUBORDINATORS:
        return None, 0.7
    if word in LISTERS:
        return None, -0.8
    # Past-tense verbs (-ed) after a comma also resume a clause, more weakly.
    if word.isalpha() and word.islower() and word.endswith("ed"):
        return None, 0.5
    # Capitalised words (names, relative clauses) after a comma are slightly negative.
    if word[:1].isupper():
        return None, -0.2
    return None, 0.0

programs.luna:
"""A sparse estimate of grammatical continuations after a comma.

It predicts modest positive activations for auxiliaries, prepositions and
clause-linking words in that position, plus a negative guess for "including".
It cannot tell whether a particular sentence uses one of these words in the
same way as the examples.
"""

READS = ()

AUXILIARIES = {
    "am", "are", "is", "was", "were", "be", "been", "being",
    "have", "has", "had", "do", "does", "did",
    "can", "could", "may", "might", "must", "shall", "should",
    "will", "would",
}
PREPOSITIONS = {
    "of", "in", "on", "at", "to", "from", "by", "for", "with",
    "as", "into", "within", "through", "after", "before", "between",
}
LINK_WORDS = {
    "who", "which", "that", "while", "where", "when", "how",
    "because", "although", "but", "and", "or",
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip()
    word = token.casefold().strip(".,;:!?()[]{}\"'“”")
    after_comma = (
        len(prefix) > 1
        and prefix.document_ids[-1] == prefix.document_ids[-2]
        and prefix.token_strings[-2].rstrip().endswith(",")
    )

    if not after_comma:
        value = 0.0
    elif word in AUXILIARIES:
        value = 0.8
    elif word in PREPOSITIONS:
        value = 0.8
    elif word in LINK_WORDS:
        value = 0.45
    elif word == "including":
        value = -0.5
    else:
        value = 0.0
    return None, float(value)

programs.sol:
"""Approximate a forward-slash separator response, mainly from token spelling.

Bare slashes are strongly positive, with lower values at URL hosts and in
paths, and higher values after numbers or single-letter variables. Quotes,
brackets, newlines, comments and HTML delimiters change the response; slashes
fused to words are generally weakly negative. TeX fraction braces and the word
"divided" provide smaller division signals. Chinese 拥/擁 (embrace) and
拥有/擁有 (possess) have a separate positive lexical response.

The only state is the previous token and at most 512 characters of the current
line, reset at document boundaries. Constants summarize training observations;
scattered word-specific background activations are deliberately left at zero.
"""
READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        line, previous = '', ''
    else:
        _, line, previous = carry
    s = prefix.token_strings[-1]
    value = 0.0
    if s == '/':
        run = line.rsplit(' ', 1)[-1]
        if '://' in run:
            value = 0.60 if '/' not in run.split('://')[-1] else 0.86
        elif previous.rstrip()[-1:].isdigit():
            value = 1.33 if '/' in run else 1.47
        elif '/' in run:
            value = 1.10
        elif len(previous.strip()) == 1 and previous.strip().isalpha():
            value = 1.44
        elif previous.startswith('.') and previous[1:].isalpha():
            value = 1.00
        else:
            value = 1.29
    elif s in (' /', '／', '╱'):
        value = 1.51
    elif s == '}{':
        value = 0.80 if any(x in line for x in ('\\frac', '\\dfrac', '\\tfrac')) else 0.20
    elif s in ('拥', '擁', '拥有', '擁有'):
        # The Chinese stem for embracing/possessing is a separate lexical response.
        value = 2.8 if len(s) == 1 else 1.68
    elif s.strip() == 'divided':
        value = 0.26
    elif s.startswith('/') and s[1:].isalpha():
        value = -0.16
        if len(s) == 2:
            value = 0.16 if s[1:].isupper() else -0.02
    elif '/' in s and not any(c.isalnum() for c in s):
        stripped = s.strip()
        if stripped.startswith('#!/'):
            value = 0.25
        elif '//' in s or '</' in s or '/*' in s:
            value = 0.0
        elif '*/' in s:
            value = 0.13 if '\n' in s else 0.34 if s.startswith(' ') else 0.78
        elif '\n' in s:
            value = 0.35 if s == '/\n' else 0.05
        elif stripped.startswith('/') and stripped.endswith('.'):
            value = -0.20
        elif '.' in s:
            value = 0.35 if any(q in s for q in ('"', "'")) else 0.80
        elif stripped.endswith('/'):
            before = stripped[:-1]
            if before in (')', '}', ']', '__'):
                value = 1.44
            else:
                value = 1.10
        elif stripped.endswith('/(') or stripped == '/\\':
            value = 1.03
    line = (line + s).replace('\\n', '\n').split('\n')[-1][-512:]
    return (doc, line, s), value

programs.haiku:
"""Layer-0 MLP down-projection feature 2181: a 'foundation / trust' word detector.

It fires on the current token when it is a word from the family of ideas
"something is founded or based on a base": foundation, found, establish, anchor,
basis, and also "trust / faith / confidence" (the things a foundation rests on).
The activation is a fixed size per word group, and 0 on everything else.
Strongest on "foundation" (about 4.5-5), then "trust" (about 2.3), "found"
(about 1.5); weaker on the rest of the group.
"""

READS = ()

# word (lowercased, without the leading space) -> typical activation
FOUNDATION = {"foundation": 4.8, "foundations": 3.9, "foundational": 2.6, "founding": 1.7,
              "基础": 1.5, "基礎": 1.1, "的基础": 1.4, "根基": 1.5}
FOUND = {"found": 1.6, "founded": 1.5, "founder": 1.2, "-found": 2.0, "-founder": 1.4}
TRUST = {"trust": 2.3, "trusted": 1.2, "trustees": 1.1, "信任": 2.0}
CONFIDENCE = {"faith": 0.9, "confidence": 1.0, "conf": 0.6, "信心": 2.0, "信": 0.4}
ESTABLISH = {"establish": 1.0, "established": 0.8, "establishment": 0.6, "establishing": 0.8, "建立": 0.6}
ANCHOR = {"anchor": 1.5, "anchors": 1.3, "anchored": 1.3, "bootstrap": 1.5, "pyramid": 1.2,
          "ramids": 1.6, "金字塔": 1.7, "shadow": 0.9, "-shadow": 1.3}
ASSOCIATION = {"association": 0.8, "associations": 0.7, "associ": 0.7, "affiliate": 0.6,
               "partnership": 0.7}
RELIANCE = {"dependency": 0.9, "dependencies": 0.6, "reliance": 1.0, "rely": 0.7, "relies": 0.7,
            "reliable": 0.4, "依赖": 1.0, "integrity": 0.6}

TABLE = {}
for group in (FOUNDATION, FOUND, TRUST, CONFIDENCE, ESTABLISH, ANCHOR, ASSOCIATION, RELIANCE):
    TABLE.update(group)


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    return carry, float(TABLE.get(word, 0.0))

programs.luna:
"""Use foundation/found words and related ideas of trust, support, and connection."""

READS = ()

_PUNCT = " \t\n\r.,;:!?()[]{}<>\"'`-"


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].casefold().strip(_PUNCT)
    if not word:
        return None, 0.0

    if word == "of" and len(prefix.token_strings) > 1:
        same_doc = prefix.document_ids[-1] == prefix.document_ids[-2]
        previous = prefix.token_strings[-2].casefold().strip(_PUNCT)
        if same_doc and previous.startswith("foundation"):
            return None, 1.2

    if word.startswith(("foundation", "基础", "基礎")):
        value = 4.6
    elif word.startswith("found"):
        value = 1.6
    elif "bootstrap" in word:
        value = 1.6
    # The tokenizer sometimes leaves "ramids" as the piece of "pyramids".
    elif word == "ramids" or "pyramid" in word:
        value = 1.8
    elif word.startswith(("trust", "信任", "信心", "信念", "可信")):
        value = 2.2
    elif word in {"信", "自信", "依"}:
        value = 0.6
    elif word.startswith(("anchor", "锚")):
        value = 1.4
    elif word.startswith(("establish", "建立", "associ", "depend", "依赖", "依靠", "reli", "confid")):
        value = 0.8
    elif word.startswith(("faith", "integrity", "basis", "basal", "fundamental", "discover", "fund")):
        value = 0.5
    elif word.startswith(("chain", "partnership", "relationship", "affiliate")):
        value = 0.4
    elif word == "基地" or word == "基" or word.startswith("基金"):
        value = 0.5
    elif word.startswith("find"):
        value = 0.25
    else:
        value = 0.0
    return None, float(value)

import re

READS = ()

"""Estimate a small lexical feature: activations are most predictable on “to” and “that”.

For those words, the preceding word often signals the direction of the response. Other
positions are predicted as zero, since the component is usually quiet.
"""

NEED_TO = {"need", "needs", "have", "want", "wants", "has"}
CAPACITY_TO = {"able", "unable", "ability", "opportunity"}
PURPOSE_TO = {"designed", "likely", "order", "required"}
RELATIONAL_TO = {"equal", "adjacent", "like", "similar", "compared", "referred"}
MANNER_TO = {"how", "according"}
REPORTING_THAT = {
    "means", "said", "say", "know", "think", "assume", "suggest", "suggests",
    "mentions", "note", "remember",
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = "" if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    match = re.search(r"([A-Za-z]+)[^A-Za-z]*$", tail)
    prior = match.group(1).lower() if match else ""

    value = 0.0
    if word == "to":
        value = 0.293
        if prior in NEED_TO:
            value = -0.95
        elif prior in CAPACITY_TO:
            value = 2.4
        elif prior in PURPOSE_TO:
            value = 1.2
        elif prior == "return":
            value = 0.65
        elif prior in RELATIONAL_TO:
            value = -0.4
        elif prior in MANNER_TO:
            value = -0.2
    elif word == "that":
        value = -0.054
        if prior in REPORTING_THAT or prior in {"such", "do"}:
            value = -1.0
        elif prior == "fact":
            value = 1.5

    return (doc, (tail + token)[-120:]), float(value)

programs.sol:
"""Lexical signal for another item, repetition, and additive transitions.

'Another' is the strongest cue. Other/next, later ordinals, also/again, and
related transition words give smaller negative signals. A few familiar phrases
adjust the strength: reciprocal 'one another', determiner + other/next,
modal + also, 'in addition', and indefinite pronoun + else. Chinese and several
other languages supply listed lexical cues. Unrecognized tokens get zero.
"""
READS = ()

# Translation equivalents and common lexical cues, grouped by strength.
ADDITIVE_LEXICON = (
    (-8.1, {'另', '另一', '另一个', '另一种'}),  # another
    (-5.5, {'另外', '另外一个'}),  # additionally / another
    (-3.3, {'otro', 'otra', 'outro', 'outra', 'autre',
            '另一方面', '另一边'}),  # another / other side
    (-3.9, {'또'}),  # also / again
    (-2.3, {'друг', 'другой', 'また', '別の'}),  # other; again
    (-1.9, {'再', 'otros', 'otras', 'outros', 'outras', 'ebenfalls'}),
    (-1.5, {'autres', 'altro', 'altri', 'altre', 'başka', 'еще', 'ещё',
            'тоже', '再次', '此外', 'もう'}),
    (-1.2, {'again', 'others', 'additionally', '其他',
            '第二', '第三', '还有', '进一步', 'さらに', '下一个', '另一半'}),
    (-1.0, {'finally', 'someone', 'weiter', 'weitere', '又', '亦'}),
    (-0.85, {'additional', '也是', '也有', '也可以'}),
    (-0.7, {'furthermore', 'moreover', 'alternate', 'fellow', '还'}),
    (-0.6, {'alternative', 'также', '最后'}),
    (-0.45, {'secondary', 'somebody', '也', 'également', 'anche',
             'cũng', 'wieder', '還'}),
    (-0.3, {'final', 'extra', 'separate'}),
)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    word = token.strip().lstrip("([{\"'’").lower()
    value = 0.0

    if word == 'another':
        value = -5.15 if previous == 'one' else -10.0
    elif word == 'other':
        value = -1.75
        if previous in {'the', 'any', 'some', 'in'}:
            value = -2.25
        elif previous in {'each', 'all', 'many', 'no', 'every', 'and', 'among'}:
            value = -1.35
    elif word == 'also':
        value = -1.1
        if previous == 'but':
            value = -0.32
        elif previous == 'and':
            value = -0.74
        elif previous == 'can':
            value = -1.62
        elif previous == 'could':
            value = -1.97
        elif previous == 'may':
            value = -1.44
    elif word in {'next', '.next', '-next'}:
        # Bare identifiers respond less than the ordinary prose word.
        value = -2.1 if token.startswith(' ') else -1.5
        if word == '.next':
            value = -0.95
        if previous == 'the':
            value = -2.85
        elif previous in {'my', 'your', 'our', 'their', 'his', 'her'}:
            value = -2.45
    elif word in {'second', 'third'}:
        value = -1.65
        if previous == 'the':
            value = -2.0
        elif previous == 'and':
            value = -1.3
    elif word in {'fourth', 'fifth'}:
        value = -1.25
    elif word in {'sixth', 'seventh', 'eighth', 'ninth', 'tenth'}:
        value = -1.0
    elif word == 'further':
        value = -1.45
    elif word in {'alternatively', 'secondly'}:
        value = -1.55
    elif word == 'similarly':
        value = -0.32 if token.strip().islower() else -0.73
    elif word == 'addition':
        value = -0.75 if previous == 'in' else -0.1
    elif word == 'different':
        value = -0.7 if previous == 'a' else 0.0
    elif word == 'else':
        if previous in {'someone', 'somebody'}:
            value = -1.0
        elif previous == 'something':
            value = -0.8
        elif previous in {'anyone', 'anything', 'anybody', 'what'}:
            value = -0.6
    else:
        for strength, words in ADDITIVE_LEXICON:
            if word in words:
                value = strength
                break
