"""Approximate the component's sparse negative response to math notation.

It marks short algebra variables and math vocabulary. A rolling text window
handles split words and gives a smaller cue to ``of`` or ``at`` after a math
term.
"""

import re

READS = ()

VARIABLE_WEIGHTS = {
    "x": -0.70, "y": -0.30, "z": -0.25, "t": -0.25, "f": -0.20,
    "u": -0.20,
}
STRONG_MATH_WORDS = {
    "asymptote", "asymptotes", "calculus", "derivative", "divergence",
    "domain", "equation", "equations", "graph", "integral", "interval",
    "intervals", "limit", "limits", "lim", "parabola", "parabolas",
    "functions", "sec", "ln", "cot", "secant", "sin", "sine", "cos",
    "cosine", "tangent", "quadratic",
}

OTHER_MATH_WORDS = {
    "area", "bound", "bounds", "circle", "coordinate", "coordinates",
    "curve", "factor", "function", "integer", "intersection", "intercept",
    "line", "maximum", "minimum", "origin", "point", "points",
    "polynomial", "ratio", "root", "roots", "slope", "transform",
    "vertex", "endpoint", "endpoints", "approach", "approaches",
    "integration", "integrating", "integrate", "expression", "expressions",
    "solution", "solutions", "satisfy", "substitute", "substitution",
}

ALL_MATH_WORDS = STRONG_MATH_WORDS | OTHER_MATH_WORDS


def _math_word_at_end(text):
    for word in ALL_MATH_WORDS:
        start = len(text) - len(word)
        if start >= 0 and text.endswith(word):
            if start == 0 or not text[start - 1].isalpha():
                return word
    return None


def _recently_math(text):
    words = re.findall(r"[a-z]+", text.casefold())
    return any(word in ALL_MATH_WORDS for word in words[-6:])


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        recent = ""
    else:
        recent = carry[1]

    text = (recent + token.casefold())[-72:]
    variable = token.strip().casefold().lstrip("([{+-")
    word = _math_word_at_end(text)
    if variable in VARIABLE_WEIGHTS:
        value = VARIABLE_WEIGHTS[variable]
    elif word in STRONG_MATH_WORDS:
        value = -0.50
    elif word in OTHER_MATH_WORDS:
        value = -0.25
    elif token.strip().casefold() in {"of", "at"} and _recently_math(recent):
        value = -0.20
    else:
        value = 0.0
    return (doc, text), float(value)

programs.sol:
"""A spelling-based detector for test words and semicolon punctuation.

Test/tests receive large positive values, with smaller responses to testing
inflections and software-testing vocabulary. Case and token boundaries affect
strength. Code-like punctuation/keywords in the last 200 characters boost
space-prefixed 'test'; function declarations boost it further.

A separate semicolon response is reduced by code context, fused brackets,
quotes, or backslashes. Line-ending combinations are weak or negative, and
HTML entity terminators are suppressed. Other tokens predict zero.
"""
import re

READS = ()
CODE = re.compile(
    r'\b(?:def|class|void|func|import|const|public|assert|async)\b'
    r'|[{}_]|\.[A-Za-z]|[/\\][A-Za-z]'
)
DECLARATION = re.compile(r'\b(?:def|void|class|func|String)\s*$')
ENTITY = re.compile(r'&(?:[A-Za-z]+|#\d+|#x[0-9a-fA-F]+)$')


def testing_word(token, recent):
    match = re.fullmatch(r'([^A-Za-z]*)([A-Za-z]+)', token)
    if not match:
        return {'测试': 1.0, 'тест': 0.76}.get(token.strip(), 0.0)
    leading, word = match.groups()
    lower = word.lower()
    capital = word[0].isupper()
    spaced = bool(leading and leading.isspace())
    code = bool(CODE.search(recent))
    if lower in {'test', 'tests'}:
        if spaced:
            if capital:
                value = 1.83 + 0.17 * code
            else:
                value = 1.35 + 0.50 * code
            if lower == 'tests':
                value -= 0.18 if code else 0.02
            if DECLARATION.search(recent):
                value += 0.48 if not capital else 0.28
        elif not leading:
            value = 1.86 + 0.28 * code
            if lower == 'tests':
                value = 1.94 if capital else 2.48
            if recent and recent[-1].isalpha() and not capital:
                value -= 0.45
        elif leading.endswith('.'):
            value = 2.04
        elif leading.endswith('_'):
            value = 1.94 if word.islower() else 1.40
        elif leading.endswith('/'):
            value = 2.0 if capital else (1.29 if lower == 'tests' else 1.71)
        elif leading.endswith('-'):
            value = 1.64
        else:
            value = 1.5
        return value
    if lower in {'testing', 'tested', 'tester', 'testers'}:
        return 0.88 + 0.22 * capital if spaced else 1.30
    if lower in {'pytest', 'unittest', 'ctest', 'junit'}:
        return {'pytest': 1.45, 'unittest': 1.05,
                'ctest': 1.30, 'junit': 0.60}[lower]
    if word.startswith('Test') and len(word) > 4 and word[4].isupper():
        return 0.8
    if lower == 'testcase':
        return 0.52
    if lower in {'mock', 'mocks', 'mocking'}:
        return 0.66 if spaced else 0.76
    if lower in {'magicmock', 'fixtures'} or word in {'SetUp', 'setUp'}:
        return 0.35
    return 0.0


def semicolon(token, recent):
    if token == '；':
        return 0.56
    if token.lstrip().startswith(';') and ENTITY.search(recent):
        return 0.0
    if '\n' in token or '\r' in token:
        return (0.09 - 0.18 * (')' in token)
                - 0.10 * max(0, token.count(')') - 1)
                - 0.08 * ('"' in token or "'" in token)
                - 0.05 * (']' in token) + 0.05 * ('}' in token))
    value = 0.71 - 0.13 * bool(CODE.search(recent))
    if token.strip() == ';' and recent and recent[-1].isalpha():
        value += 0.05
    value -= 0.31 * token.count(')') + 0.15 * token.count('(')
    value -= 0.29 * ('"' in token or "'" in token)
    value -= 0.24 * (']' in token) + 0.18 * ('}' in token)
    value -= 0.25 * ('\\' in token)
    if any(c.isalpha() for c in token):
        value -= 0.30
    return max(-0.15, value)


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    recent = '' if carry is None or carry[0] != document else carry[1]
    token = prefix.token_strings[-1]
    if ';' in token or token == '；':
        value = semicolon(token, recent)
    else:
        value = testing_word(token, recent)
    return (document, (recent + token)[-200:]), float(value)

