"""Collecting, gathering, and forming sets, recognized from token spelling.

集 (gather/collection) is the strongest cue. Gather and collect words
follow, then set/group/select/add and related aggregation words. A short
word tail handles split spellings and aggregation phrases ending in 'of'.
集 is weakened after editing/data-set cues, and strengthened after 全
(complete/all) or a digit (as in episode numbers). Other tokens predict zero.
"""
import re

READS = ()


def lexical(token):
    s = token.strip().strip('._-/\\(){}[],:;<>"\'')
    w = s.lower()
    if s == '集':
        return 8.0
    if s == '集中':
        return 6.7
    if s in {'集团', '集團'}:
        return 1.5
    if s.startswith('集'):
        return 3.4 if len(s) == 2 else 1.5
    if s == '聚集':
        return 3.3
    if s in {'聚', '汇', '匯'}:
        return 2.3 if s == '聚' else 1.2
    if '集' in s:
        return 1.7
    if s in {'群', '群体', '群體', '众', '眾', '团结', '團結'}:
        return 1.0
    if s in {'合', '加', '组', '組', '选', '選', '选择', '選擇', '添加', '添'}:
        return 0.6
    if s in {'집', 'tập', 'セット', 'グループ', 'まとめ'}:
        return {'집': 4.7, 'tập': 3.6, 'セット': 1.25,
                'グループ': 0.75, 'まとめ': 0.9}[s]
    if w.startswith('collectiv'):
        return 2.1 if w.endswith('ly') else 3.45
    if w.startswith('collect'):
        if w.startswith('collection'):
            return 1.85 if token.startswith(' ') and s[0].islower() else 1.45
        return 1.7 if w.startswith('collector') else 2.3
    if w.startswith('gather'):
        return 2.7 if w in {'gather', 'gathered'} else 2.3
    if w in {'set', 'sets'}:
        return 1.6 if w == 'sets' and token.startswith(' ') else 1.2
    if re.match(r'^(set|Set)[A-Z]', s):
        return 0.7
    if w in {'dataset', 'datasets', 'subset', 'subsets', 'hashset'}:
        return 0.85
    if w.startswith('select'):
        return 0.2 if w.startswith('selector') else 0.75
    if w.startswith(('group', 'subgroup')):
        return 0.85
    if w.startswith('cluster'):
        return 1.1
    if w in {'together', 'altogether'}:
        return 1.05 if w == 'together' else 0.55
    if w in {'addition', 'additions'}:
        return 0.2
    if w in {'add', 'adds', 'added', 'adding'}:
        return 0.75 if w == 'add' and not token.startswith('.') else 0.6
    if w.startswith('concentr'):
        return 1.0 if 'tion' in w else 1.5
    if w.startswith(('assembl', 'accumul', 'aggreg')):
        return 1.05
    if w.startswith('combin'):
        return 0.2 if 'tion' in w else 0.55
    if w.startswith('integrat'):
        return 0.7 if w == 'integrated' else 0.3
    if w.startswith(('consolid', 'converg', 'compil')):
        return 0.55
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    tail = '' if carry is None or carry[0] != doc else carry[1]
    value = lexical(token)
    if token == '集':
        if tail.endswith(('編', '编辑', '数据', '數據', '训练', '資料')):
            value = 5.0
        elif tail.endswith('全') or (tail and tail[-1].isdigit()):
            value = 9.0
    if token.lower() == ' of':
        match = re.search(r'[A-Za-z]+$', tail)
        if match:
            noun = match.group()
            value = 0.6 * lexical(' ' + noun)
            if noun.lower() in {'set', 'sets', 'subset', 'subsets'}:
                value = 0.25
    if value == 0.0 and token.isascii() and token.isalpha():
        match = re.search(r'[A-Za-z]+$', tail)
        if match:
            joined = match.group() + token
            strength = lexical(joined)
            if strength >= 0.8:
                completes_collect = (
                    joined.lower().startswith('collect') and len(token) > 3
                )
                scale = 1.0 if completes_collect else 0.65
                value = scale * strength
    return (doc, (tail + token)[-40:]), float(value)

