    value = 0.0
    if any(root in word for root in ("collect", "gather", "cluster", "aggregate")):
        value = 1.35

    if "dataset" in word:
        value = max(value, 1.0)
    bare = word.strip(" .,_-/\\'\"()[]{}:;!?")
    if bare in {"set", "sets"} or "_set" in lower:
        value = max(value, 0.85)
    if "group" in word:
        value = max(value, 0.60)

    if any(root in word for root in ("select", "choos")):
        value = max(value, 0.55)
    if "together" in word:
        value = max(value, 1.0)
    if any(root in word for root in ("combin", "join", "union")):
        value = max(value, 0.55)
    if bare in {"add", "added", "adding", "adds"}:
        value = max(value, 0.45)
