programs.sol:
"""A token-text approximation of strong code/name-continuation responses.

Recognized names following import-like words, URL hosts, and include headers
receive positive values.
Import-token whitespace weakens the response. Recognizable lint/preprocessor
markers, Rust/Go/PHP idioms, shell delimiters and a patent structure placeholder
have additional positive rules.
A few programming names have a small background response. Other contexts,
including scattered natural-language lexical pairs, are left at zero.
Only the previous token is remembered, and document boundaries reset it.
"""

READS = ()

# Common roots of Java/Android imports, with their characteristic strengths.
IMPORT_ROOTS = {
    'java': 2.05, 'javax': 2.0, 'javafx': 1.8,
    'android': 1.6, 'androidx': 1.8, 'org': 1.6,
    'com': 1.3, 'net': 1.3, 'io': 0.9,
    'cn': 0.8, 'br': 0.5, 'edu': 1.65,
    'lombok': 2.2, 'butterknife': 2.2, 'junit': 1.7,
}
NUMERIC_MODULES = set('''numpy scipy pandas matplotlib seaborn sklearn
    tensorflow keras torch sympy'''.split())
GUI_MODULES = {'tkinter', 'pygame', 'PyQt', 'PySide', 'UIKit', 'React'}
OS_MODULES = {'os', 'sys', 'pathlib', 'pickle', 'shutil'}
MODULES = set('''re json datetime math collections typing urllib itertools
    functools asyncio threading multiprocessing subprocess socket logging
    argparse unittest tempfile heapq traceback inspect statistics abc copy csv
    io glob contextlib requests pytest tqdm sqlalchemy pymongo bs PIL django
    flask werk boto dist nltk serial retrofit okhttp mongoose'''.split())
HEADERS = set('''stdio stdlib stdint stddef stdarg stdbool iostream fstream
    sstream unistd cstdio cstdlib cassert vector string algorithm math cmath
    assert sys time limits memory map set queue stack unordered boost linux
    fcntl arpa netinet glm stdafx'''.split())
HASH_DIRECTIVES = {
    'region': 0.9, 'endregion': 0.9, 'pragma': 0.9, 'noqa': 1.1,
    'pylint': 0.9, 'ifdef': 0.5, 'ifndef': 0.5, 'endif': 0.35,
    'include': 0.13,
}
COMMENT_TAGS = {
    'TODO': 0.8, 'FIXME': 0.8, 'XXX': 0.35, 'Copyright': 0.7,
    'eslint': 1.7, 'noinspection': 2.0, 'NOI': 1.5, 'MARK': 1.5,
}
# Conventional syntactic pairs, not general word-pair memorization.
SYNTAX = {
    ('namespace', 'std'): 0.36,
    ('require', '_once'): 0.58, ('include', '_once'): 0.58,
    (',', 'err'): 0.14, ('return', 'err'): 0.14,
    ('!=', 'nil'): 0.28, ('==', 'nil'): 0.22,
}


def module_strength(word):
    if word in IMPORT_ROOTS:
        return IMPORT_ROOTS[word]
    if word in NUMERIC_MODULES or word in GUI_MODULES:
        return 1.45
    if word in OS_MODULES:
        return 1.35
    if word in MODULES:
        return 1.05
    if word in {'random', 'time'}:
        return 0.5
    return 1.2 if word == 'static' else 0.2


def response(token, previous):
    word, marker = token.strip(), previous.strip()
    if marker in {'import', 'from', 'package'} and token.startswith(' '):
        if word.isidentifier():
            value = module_strength(word)
            if marker == 'package':
                return 0.45 * value
            if marker == 'from':
                if previous.startswith(' ') and value == 0.2:
                    return 0.0
                return value * (0.9 if previous == 'from' else 0.75)
            discount = 0.6 if previous.startswith(' ') else 0.45
            return value if previous == 'import' else max(0.0, value-discount)
    if marker == 'static' and word in IMPORT_ROOTS:
        return 0.65
    if marker == 'using' and not previous.startswith(' '):
        return {'System': 1.1, 'Microsoft': 1.1, 'UnityEngine': 2.0,
                'UnityEditor': 2.0, 'namespace': 0.75}.get(word, 0.0)
    if previous == '://' and word.isalnum():
        if word in {'www', 'localhost'}:
            return 0.25
        if word in {'docs', 'schemas', 'creativecommons', 'developers'}:
            return 1.05
        if word in {'repo', 'api', 'groups', 'chat', 'maps', 'git'}:
            return 0.75
        return 0.4
    if marker in {'<', '"'} or marker.endswith(('include', 'include "')):
        header = word.lstrip('<')
        if header in HEADERS:
            if header in {'stdlib', 'unistd', 'fstream', 'linux', 'fcntl',
                          'arpa', 'glm'}:
                return 1.5
            if header in {'stdio', 'sys', 'stdarg', 'cassert', 'cstdlib'}:
                return 1.2
            return 0.55 if header in {'string', 'math', 'time', 'stack'} else 0.9
    if marker in {'&', '(&'}:
        return {'mut': 0.6, 'self': 0.4, 'str': 0.24}.get(word, 0.0)
    if marker == '#' and word in HASH_DIRECTIVES:
        return HASH_DIRECTIVES[word]
    if marker in {'#', '//', '/*'} and word in COMMENT_TAGS:
        return COMMENT_TAGS[word]
    if marker == 'for' and word == '_,':
        return 0.9 if previous.startswith(' ') else 1.1
    if marker == 'if' and word == 'err':
        return 0.5 if previous.startswith('\t') else 0.33
    if word == 'EOF' and marker in {'<<', "'", '"'}:
        return 0.75
    if marker.endswith('#') and word == '!/':
        return 1.0
    # Chemical-structure placeholder convention in patent text.
    if marker == '##' and word == 'STR':
        return 1.5
    if token in {'import', '\timport'}:
        return 0.08
    if (marker, word) in SYNTAX:
        return SYNTAX[marker, word]
    if token.startswith(' '):
        if word in {'java', 'javax', 'javafx'}:
            return 0.35
        if word in {'android', 'org'}:
            return 0.22
        if word in NUMERIC_MODULES or word in {'np', 'pd'}:
            return 0.15
        if word in {'err', 'nil'}:
            return 0.07
    return 0.0


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    return (doc, token), float(response(token, previous))

