# value of the token right after each keyword (measured means, 'import' split by context)
AFTER = {"using": 0.6, "package": 0.3, "from": 0.25, "://": 0.4, " ##": 0.9}

def step(carry, prefix, upstream):
    s = prefix.token_strings
