    if len(s) < 2 or docs[-1] != docs[-2]:
        return None, 0.0          # first token of a document: no keyword before it
    prev, cur = s[-2], s[-1].strip()
    before = s[-3] if len(s) > 2 and docs[-3] == docs[-1] else ""
    if prev == "import":
        if before.endswith(";"):          # Java / C#-style statement
            value = 2.0 if cur in JAVA_ROOTS else 1.5
        elif before.endswith("\n"):       # line-start import, e.g. Python
            value = 0.85
        else:
            value = 0.1
    else:
        value = AFTER.get(prev, 0.0)
    return None, float(value)

programs.luna:
"""A small text heuristic for sparse activations in technical prose.
It gives modest scores to selected library/code words near code cues, to a
few formal legal terms, and to alphabetic pieces near URLs; other tokens get
zero. It resets its short text memory when the document changes. The harvest
also includes multilingual cases this compact rule does not try to cover.
"""
READS = ()

CODE_HINTS = (
    'import ', 'from ', 'package ', 'class ', 'public ', 'private ',
    'typedef ', '#include', 'fn ', 'mut ', 'self', 'def ', 'function ',
    'require', 'using ', '->', '::', '=>', '```', 'python', 'java',
    'javascript', 'typescript', 'golang', 'php', 'npm', 'rust',
)

TECH_WORDS = {
    'java', 'javafx', 'javax', 'tkinter', 'urllib', 'distutils',
    'pickle', 'vector', 'string', 'io', 'mut', 'endregion', 'region',
    'noqa', 'typescript', 'nonnull', 'require_once', 'err',
}

LEGAL_WORDS = {
    'moot', 'pertinent', 'wherefore', 'affidavit', 'affidavits',
    'petitioner', 'vacates', 'rulings',
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail = ''
    else:
        tail = carry[1]
    nearby = (tail + token).lower()
    word = token.strip().lower()
    code = any(hint in nearby for hint in CODE_HINTS)
    url = 'http://' in nearby or 'https://' in nearby or 'www.' in nearby
    if word in TECH_WORDS and code:
        value = 0.45
    elif word in LEGAL_WORDS:
        value = 0.35
    elif url and word.isascii() and word.isalpha():
        value = 0.20
    else:
        value = 0.0
    return (doc, (tail + token)[-160:]), float(value * 0.35)

