    '不同的': 0.7, '相关': 1.08, '大家': 0.58, '什么': 0.8,
    '色々': 5.5, '様々な': 4.5, '様々': 3.0,
    'さまざまな': 5.2, 'さまざま': 3.7, 'いろいろ': 4.8,
