COLLECTION_OF = {
    'varieties': 1.7, 'array': 1.65, 'assortment': 2.2, 'myriad': 1.85,
    'plethora': 1.4, 'multitude': 1.35, 'types': 1.15, 'series': 1.1,
    'bunch': 1.15, 'kinds': 0.95, 'sorts': 0.95, 'spectrum': 1.05,
    'diversity': 1.05, 'list': 0.72, 'collection': 0.7, 'group': 0.45,
    'set': 0.35, 'combination': 0.4, 'selection': 0.45,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, strength = ('', 0.0)
    if carry is not None and carry[0] == doc:
        previous, strength = carry[1:]
    raw = prefix.token_strings[-1]
    word = raw.strip().lower()
    value = WORDS.get(word, TRANSLATIONS.get(word, 0.0))

    if word == 'various' and raw.strip() == 'Various':
        value = 8.0 if raw == 'Various' else 8.35
    elif raw == 'Several':
        value = 2.8
    elif raw.strip() == 'What':
        value = 0.88
    elif word in {'var', '_var', 'vari'}:
        value = 0.55 if word == 'var' else 0.8
    elif word == 'ious' and previous == 'var':
        value = 8.2
    elif word == 'ly' and previous == 'various':
        value = 2.5
    elif word == 'other':
        value = {'each': -0.26, 'any': 0.05, 'some': 0.05, 'no': 0.05,
                 'every': 0.05, 'the': 0.4, 'and': 0.78, 'with': 0.78,
                 'as': 0.78, 'various': 2.6}.get(previous, 0.64)
    elif word == 'following':
        value = 0.8 if previous == 'the' else 0.0
    elif word == 'few':
        value = 0.4 if previous == 'a' else -0.08
    elif word == 'many':
        value = -0.13 if previous == 'how' else 0.18
    elif word == 'different':
        comparison_context = {'a', 'completely', 'significantly', 'slightly', 'very', 'is'}
        value = 0.27 if previous in comparison_context else 0.7
    elif word == 'number':
        value = 0.6 if previous == 'a' else -0.05
    elif word == 'variety':
        value = {'a': 1.8, 'wide': 2.4}.get(previous, 1.3)
    elif word == 'range':
        value = {'a': 0.65, 'full': 0.55, 'wide': 1.3,
                 'diverse': 1.1, 'broad': 0.9}.get(previous, 0.1)
    elif word == 'of':
        value = COLLECTION_OF.get(previous, 0.0)
        # Continue the graded collection signal through its preposition.
        if previous == 'range':
            value = 1.1 + 1.25 * strength
        elif previous == 'variety':
            value = 2.3 + strength
        elif previous == 'number':
            value = 0.15 + 1.4 * strength
        elif previous in {'one', 'most', 'both', 'some', 'many', 'none', 'those'}:
            value = -0.2

    if word not in TRANSLATIONS:
        if '各' in word:
            expression = word[word.index('各'):]
            value = TRANSLATIONS.get(expression, 3.5)
            if word != expression:
                value *= 0.9
        elif word.startswith('verschied'):
            value = 2.5
        elif word.startswith('verschill'):
            value = 2.3
        elif word.startswith('различ'):
            value = 4.0
