"""Variety detector for layers.0.mlp.down_proj:2191 (a component of layer 0's MLP).

What it does: it fires on the word that opens a list of mixed or unspecified things.
- Strongest (about 9): English "various", and the Chinese word 各种 ("various kinds").
- Strong (about 5): other "various" words, such as 各 (Chinese), 色々 / さまざま (Japanese),
  различные (Russian), 여러 (Korean).
- Moderate (about 2): "several", "numerous", "assorted", "diverse", "whatever",
  "respective", "variety", and their foreign-language kin (plusieurs, varias, các).
- Weak (about 0.8): everyday indefinite words such as "some", "any", "each", "every",
  "other", "different", "what", "similar", "following".
- The "of" after a word of variety fires too: "a variety of" (about 4), "a range of",
  "an array of", "types of", "series of" (about 1.5), "a list of", "a set of" (about 0.5).
- Everything else, including articles, "many", "much", "all", "this", "that", is about zero.

Why: this is a "various" concept detector. Its value is set by the word alone, so it does
not need any memory of earlier tokens.
"""

READS = ()

VARIOUS = {" various", " Various", "various", "Various", " VARIOUS", "各种", "各種", "各类", "各類",
           "各个", "种种", "種種"}
TRANSLATED = {"各", "各地", "各位", "各项", "各级", "各大", "色々", "様々な", "さまざまな",
              "さまざま", " различные", " различных", " разных", " 여러", " 다양한"}
SEVERAL = {" several", " Several", "Several", " numerous", " assorted", " diverse", " whatever",
           " Whatever", " respective", " variety", " varying", " varied", " plethora",
           " plusieurs", " varias", " các"}
INDEFINITE = {" some", " Some", "Some", " any", " Any", "Any", " each", " Each", " every",
              " other", " different", " what", " What", " similar", " following", " own",
              " certain", " related", " relevant", " appropriate", " individual", " plenty"}
VARIETY_NOUNS = {" variety", " varieties", " assortment"}
KIND_NOUNS = {" range", " array", " types", " series", " spectrum", " kinds", " stages", " bunch"}
COLLECTION_NOUNS = {" list", " collection", " set", " group", " combination", " mixture",
                    " plurality", " sequence", " lots", " handful", " number"}

def step(carry, prefix, upstream):
    word = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    if word in VARIOUS:
        value = 9.0
    elif word in TRANSLATED:
        value = 5.0
    elif word in SEVERAL:
        value = 2.0
    elif word in INDEFINITE:
        value = 0.8
    elif word == " of" and prev in VARIETY_NOUNS:
        value = 4.0
    elif word == " of" and prev in KIND_NOUNS:
        value = 1.5
    elif word == " of" and prev in COLLECTION_NOUNS:
        value = 0.5
    else:
        value = 0.0
    return carry, float(value)

programs.sol:
"""Approximate conversation markup and qualified code-name pulses.

Chat starts, thinking tags, and tool markup give large positive pulses.
Dot-prefixed capitalized identifiers give smaller ones, boosted in imports
or after lowercase namespace segments. Initials and sentence-start function
words are exceptions. Identifier length, CamelCase parts, capitalized names
attached to other punctuation, and Error/Exception suffixes refine the pulse.
Other tokens generally receive zero. State resets at document boundaries.
"""
import re

READS = ()
MARKERS = {
    '<think>': 1.13,
    '</think>': 2.20,
    '<tool_call>': 3.16,
    '</tool_call>': 1.94,
    '<tool_response>': 2.14,
    '</tool_response>': 2.17,
    '<|im_end|>': -0.05,
}
SENTENCE_STARTERS = {
    'A', 'An', 'The', 'I', 'He', 'She', 'It', 'We', 'You', 'They',
    'This', 'That', 'These', 'Those',
}
INITIAL = re.compile(r' ?[A-Z]$')
WORDS = re.compile(r'[A-Z]?[a-z]+|[A-Z]+(?=[A-Z][a-z]|$)')
IMPORT = re.compile(r'\bimport\b')
CAPITAL_PREFIXES = {
    '(': 0.35, '_': 0.35, '/': 0.35, '<': 0.35, '[': 0.35,
    '\\': 0.9, '@': 0.6, '-': 0.35,
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    start = carry is None or carry[0] != doc
    previous, importing = ('', False) if start else carry[1:]
    value = MARKERS.get(token, 0.0)
    if token == '<|im_start|>':
        value = 1.12 if start else 1.99
    elif token == '<tool_call>':
        value = 3.23 if ':' in previous else 3.09
    elif len(token) > 1 and token[0] == '.' and token[1:].isalpha():
        word = token[1:]
        namespace = (previous.startswith('.') and
                     previous[1:].isalpha() and previous[1:].islower())
        if word in SENTENCE_STARTERS:
            value = 0.17
        elif word[0].isupper():
            if len(word) == 1:
                value = 0.0 if INITIAL.fullmatch(previous) else 0.33
                if value:
                    value += 0.4 * importing + 0.4 * namespace
            elif word.isupper():
                value = 0.62 + 0.2 * importing + 0.5 * namespace
            else:
                parts = len(WORDS.findall(word))
                value = 0.82 + 0.05 * min(len(word), 8)
                value += 0.1 * max(0, parts - 1)
                value += 0.38 * importing + 0.4 * namespace
                if previous.isdigit():
                    value -= 0.27
                elif INITIAL.fullmatch(previous):
                    value -= 0.55
        else:
            parts = len(WORDS.findall(word))
            value = -0.02 + 0.023 * min(len(word), 10)
            value += 0.15 * max(0, parts - 2) + 0.1 * importing
    else:
        word = token.strip()
        if len(token) > 2 and token[0] in CAPITAL_PREFIXES:
            word = token[1:]
            if word.isalpha() and word[0].isupper():
                value = CAPITAL_PREFIXES[token[0]]
                if word.isupper() and token[0] not in '\\@':
                    value = 0.12
        elif word.isascii() and word.isalpha():
            parts = len(WORDS.findall(word))
            if parts > 1:
                value = (0.26 if word[0].isupper() else -0.08)
                value += 0.25 * min(3, parts - 2)
            if len(word) > 5 and word.endswith(('Error', 'Exception')):
                value += 0.3
    if '\n' in token or ';' in token:
        importing = False
    if IMPORT.search(token.rsplit('\n', 1)[-1]):
        importing = True
    return (doc, token, importing), float(value)

