"""Approximate a mixed lexical signal using names, spelling, and chat markup.

README and JavaScript testing/linting names get strong positive responses.
Camel-case identifiers and consonant acronyms get weaker ones. A few chat
boundary markers have signed responses. Small -ing/-ly bonuses describe
another weak spelling tendency, not an analysis of sentence meaning.
Most unrelated token-specific responses are deliberately left unexplained.
"""
import re

READS = ()

# Boundaries in tool-using conversations, plus ordinary message boundaries.
BOUNDARIES = {
    '</tool_call>': -0.24,
    '<tool_response>': 0.18,
    '</tool_response>': 0.12,
    '<|im_end|>': 0.043,
    '<|im_start|>': 0.023,
    '<think>': 0.055,
    '</think>': -0.05,
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token in BOUNDARIES:
        return None, BOUNDARIES[token]
    stripped = token.strip()
    name = stripped.lstrip('.(_/<:@\\\'"`-')
    if name.lower() == 'readme':
        return None, 0.66
    if name == 'eslint':
        return None, 0.22 if token.startswith(' ') else 0.36
    if name in ('toBe', 'toHave', 'toEqual'):
        return None, {'toBe': 0.65, 'toHave': 0.48, 'toEqual': 0.33}[name]
    value = 0.0
    if name.isascii() and name.isalpha():
        if re.search('[a-z][A-Z]', name):
            value = 0.12
            if stripped.startswith('.'):
                value -= 0.055
            if name.startswith(('get', 'Get')):
                value -= 0.05
            if name.startswith(('set', 'Set')):
                value -= 0.09
            if name.startswith(('on', 'On')):
                value += 0.10
        elif name.isupper() and token.startswith((' ', '\t')):
            if 2 <= len(name) <= 5 and not any(c in 'AEIOU' for c in name):
                value += 0.09
            if len(name) == 3:
                value += 0.04
        elif name.islower() and len(name) > 5:
            if name.endswith('ing'):
                value += 0.015
            if name.endswith('ly'):
                value += 0.02
    return None, value

