"""Local contrast between opening reference words and in-phrase demonstratives.

Capitalized This/These produce large positive pulses; The/Here/Such produce
smaller ones. Lowercase this/these are negative after object prepositions and
verbs, but change sign after separators or certain opening connectors. A mild
position gain captures stronger responses near a document's beginning.
Selected non-English demonstratives follow similar rules. No referent tracking
is attempted; unlisted tokens are predicted as zero.
"""
import math

READS = ()

# Grammatical contexts, not token identifiers.
OBJECT_PREPOSITIONS = set('in on at for with about under using between'.split())
LINKS = set('and but because'.split())
COMPLEMENTS = set('that so how then whether'.split())
# Inflected forms of proximal demonstratives: French, Romance, German, Russian.
OTHER_DEMONSTRATIVES = set('cette este esta estos estas questa '
                          'dieser dieses diesen diesem diese этот эту этой этих'.split())


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip()
    start = (len(prefix.document_ids) == 1 or
             prefix.document_ids[-1] != prefix.document_ids[-2])
    doc = prefix.document_ids[-1]
    position = 0 if carry is None or carry[0] != doc else carry[1] + 1
    # A mild early-document amplification, fading with distance from the start.
    gain = 1.2 - 0.04 * math.log1p(position) + 0.9 / (position + 1)
    previous = '' if start else prefix.token_strings[-2]
    prev = previous.strip()
    lower = prev.lower()
    period = prev.endswith('.') and '\n' not in previous
    newline = '\n' in previous
    spaced = token.startswith(' ')
    value = 0.0

    if word in ('This', 'These'):
        if start:
            value = 8.84 if spaced else 5.45
        elif period and spaced:
            value = 5.12
        elif previous.isspace() or newline:
            value = 4.05 if spaced else 3.92
        elif prev and any(c.isalnum() for c in prev):
            value = 3.0
        else:
            value = 3.95 if spaced else 3.25
        if word == 'These':
            value -= 0.5
            if start:
                value = 4.13
        if not start and period and spaced:
            value *= gain
    elif word == 'The':
        if start:
            value = 2.26 if spaced else 2.43
        elif period or newline or previous.isspace():
            value = 1.12 if period else 1.06
        else:
            value = 0.77
        if not start:
            value *= gain
    elif word in ('Here', 'Such'):
        value = 1.92 if period and spaced else (1.55 if spaced else 1.3)
    elif word in ('this', 'these', 'such') and spaced:
        value = -1.0
        if lower in OBJECT_PREPOSITIONS:
            value = -1.5
        elif lower in ('make', 'return'):
            value = -1.9
        elif lower in COMPLEMENTS or prev == '=':
            value = -0.4
        elif lower in LINKS:
            value = 0.1
        elif prev in (',', ':', '-', '—', '–'):
            value = 0.4
        elif prev in ('.', ';'):
            value = 0.9
        elif previous.isspace() or newline or start:
            value = 0.4
        if prev[:1].isupper():
            value = -0.1
            if lower in ('for', 'on', 'at', 'from', 'and', 'but', 'because'):
                value = 0.5
            if lower == 'in':
                value = 0.86
            elif lower in ('during', 'however'):
                value = 1.3
            elif lower == 'with':
                value = 0.03
        if word == 'these':
            value = value * 0.67 if value < 0 else value + 0.2
        elif word == 'such':
            value *= 0.25 if value < 0 else 0.8
        if value < 0:
            value *= gain
    elif word in ('.This', '>This'):
        value = 2.95
    elif word in ('"This', '“This'):
        value = 1.95
    elif word == '.The':
        value = 0.66
    elif word in OTHER_DEMONSTRATIVES and spaced:
        value = -1.25
    elif word in ('Cette', 'Este', 'Esta', 'Diese', 'Этот', 'Это'):
        value = 1.8
    elif word in ('Die', 'Das'):
        value = 0.8 if word == 'Die' else 0.45
