    '<|im_end|>': -0.046,
    '<think>': -0.084,
    '</think>': -0.138,
    '<tool_call>': -0.061,
    '</tool_call>': 0.040,
    '<tool_response>': 0.046,
    '</tool_response>': 0.013,
