    "family", "friendly", "lovely", "only", "early", "silly",
})


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, old_doc = carry if carry is not None else ("", doc)
    if doc != old_doc:
        previous = ""

    part = prefix.token_strings[-1].lower()
    cut = max(part.rfind(" "), part.rfind("\n"), part.rfind("\t"))
    tail = part[cut + 1:]
    letters = "".join(ch for ch in tail if ch.isalpha())
    if cut >= 0 or any(not ch.isalpha() for ch in tail):
        word = letters
    else:
        word = previous + letters
    word = word[-32:]

    if word.endswith("ly") and len(word) > 3 and word not in LY_EXCEPTIONS:
        value = -3.8
    elif word in LINKING_ADVERBS:
        value = -1.2
    else:
        value = -0.025
