            return -1.9
    if s == word and len(low) == 2 and low[1] == 'y' and low[0] in 'eoiu':
        return -0.7
    if low in ('eye', 'eyes') and spaced:
        return -0.9 if low == 'eye' else -0.25
    if low.startswith('y'):
        if low.startswith('your'):
            return -0.03 if spaced and not capital else -0.2
        if low in ('you', 'youtube'):
            if capital:
                return -1.6
            return -0.94 if spaced else -2.0
        if low.startswith('year'):
            value = -2.0 if low.startswith('years') else -2.56
            return value - (0.7 if capital else 0.0)
        if low.startswith('young'):
            value = -1.78
            if low.startswith('youngest'):
                value = -0.84
            elif low.startswith('younger'):
                value = -1.4
            return value - (0.9 if capital else 0.0)
        if low.startswith('youth'):
            return -2.1 if capital else -1.36
        if low.startswith(('yes', 'yeah', 'yep')):
            if low.startswith('yesterday'):
                return -1.62
            return -3.07 if capital else -2.81
        if low == 'yet':
            return -2.13 if capital else -1.53
        if low.startswith('yellow'):
            return -3.2
        if low.startswith('yield'):
            if low == 'yields':
                return -1.62
            return -1.84 if low == 'yielded' else -2.24
        if low.startswith(('yaml', 'yml')):
            return -2.2 if s.startswith('.') else -2.6
        if len(low) == 1:
            if s == word and previous[-1:].isalpha():
                if capital:
                    return -0.5 if previous[-1:].isupper() else -2.4
                return -1.4 if previous[-1:].lower() in 'aeiou' else -0.8
            if capital:
                return -2.77
            if spaced:
                return -1.6
            if s.startswith(('.', '/', '\\')):
                return -2.7
            return -1.9 if s != word else -2.4
        if low == 'ying':
            return -0.95
        if low[1] in 'aeiou':
            if len(low) <= 3:
                base = {'a': -3.3, 'e': -4.1, 'i': -2.7,
                        'o': -3.5, 'u': -3.2}[low[1]]
                return base - (1.2 if capital else 0.0)
            return -3.4 if capital else -2.8
        if low.startswith('yy'):
            return -2.3
        return -1.5 if s != word else 0.0
    if word in ('や', 'よ', 'ゆ', 'ヤ', 'ヨ', 'ユ', 'よう'):
        if word.startswith('よう'):
            return -1.6
        if word[:1] in 'ヤヨユ':
            return -4.0
        return -1.45 if word == 'ゆ' else -2.55
    if len(word) <= 2 and word.startswith(('я', 'Я')):
        return -2.0 if capital else -1.5 if spaced else -0.8
    if word == 'ي':
        return -1.6 if spaced else -0.2
    if len(word) == 1 and '\uac00' <= word[0] <= '\ud7a3':
        # Unicode's syllable names expose the romanized y-vowel syllables.
        syllable = unicodedata.name(word).removeprefix('HANGUL SYLLABLE ')
        if syllable.startswith(('YA', 'YE', 'YO', 'YU')):
            strong = syllable.startswith('YA') or (
                syllable.startswith('YE') and not syllable.startswith('YEO'))
            return -2.3 if strong else -1.25
    # Year vocabulary also responds across languages.
    if word == '년' or ('年' in word and len(word) <= 2):
        return -1.05
    if low in ('год', 'году', 'года', 'лет'):
        return -0.65
    # Common Mandarin characters with y-initial readings. These are syllable
    # families, not token IDs; function characters such as '也' are omitted.
    if len(word) == 1:
        if word in '亚亞牙雅呀涯芽押崖丫叶葉耶':
            return -1.8
        if word in '扬揚阳陽杨楊洋羊姚瑶瑤摇搖腰':
            return -1.7
        if word in '言颜顏严嚴岩烟煙艳艷宜怡永勇幽':
            return -1.2
        if word in '玉鱼魚雨宇友游遊油優尤约約云雲':
            return -0.9
    if word == 'يا':
        return -1.1
    if word == 'ย':
        return -3.1
    # Join split y-syllables, with weaker values for longer continuations.
    if (word and s == word and word[:1].lower() in 'aeiou'
            and previous.lower().endswith('y')):
        if previous.strip().lower() == 'y':
            return -1.0
        return -max(0.1, 1.4 - 0.25 * len(word))
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, language = '', 0.0
    else:
        previous, language = carry[1:]
    s = prefix.token_strings[-1]
    value = token_response(s, previous)
    # Approximate the weaker response to conjunction y in Spanish-like text.
    if s == ' y':
        value = -0.92 if language > 0.0 else -1.97
    word = s.strip().lower()
    language = (0.9 * language + (word in SPANISH_WORDS)
                - (word in FRENCH_WORDS)
                + 0.7 * any(c in s for c in 'ñ¿¡'))
    return (doc, s, language), float(value)

programs.luna:
"""Approximate the preference for y-onset pieces, especially ye/ya spellings.

It also recognizes the corresponding kana and hangul syllables. Common
"your" pieces are weak, while a few y-starting subword endings are neutral.
"""

import unicodedata

READS = ()

HAN_Y_ONSETS = frozenset("阳陽洋云雲亚亞葉叶嫣")
HAN_YEAR = frozenset(("年", "去年", "每年"))
Y_CONTINUATIONS = ("yn", "ym", "ys", "yl", "yp")


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    piece = raw.lstrip()
    start = next((i for i, char in enumerate(piece) if char.isalpha()), None)
    if start is None:
        return carry, 0.0

    word = piece[start:]
    lower = word.lower()
    first = word[0]
    name = unicodedata.name(first, "")

    previous = ""
    if prefix.position and prefix.document_ids[-1] == prefix.document_ids[-2]:
        previous = prefix.token_strings[-2]
    continuation = (
        not raw[:1].isspace()
        and previous
        and previous[-1].isalnum()
    )

    if first in HAN_Y_ONSETS:
        value = -1.8
    elif word in HAN_YEAR:
        value = -1.0
    elif name.startswith(("HIRAGANA LETTER YA", "KATAKANA LETTER YA")):
        value = -2.6
    elif name.startswith(("HIRAGANA LETTER YO", "KATAKANA LETTER YO")):
        value = -1.2
    elif name.startswith("HANGUL SYLLABLE Y"):
        value = -2.0
    elif name.endswith("LETTER YA"):
        value = -0.8
    elif continuation and lower.startswith(Y_CONTINUATIONS):
        value = 0.2
    elif first.lower() == "y":
        if lower.startswith("your"):
            value = 0.0
        elif lower == "ye":
            value = -3.8
        elif lower.startswith(("year", "yes", "yea", "ye")):
            value = -2.6
        elif lower.startswith("ya"):
            value = -2.7
        elif lower.startswith("you"):
            value = -1.0 if first.islower() else -1.6
        elif lower.startswith("young"):
            value = -1.8 if first.islower() else -2.4
        elif lower.startswith("york"):
            value = -3.2
        elif lower.startswith("yo"):
            value = -0.9
        else:
            value = -1.4 if first.islower() else -2.0
    else:
        value = 0.0

    return carry, value

programs.sol:
"""A lexical security detector with separate chat-format responses.

The largest negative responses occur on 'security', several Chinese security
or after-sales-service words, and mystery words. Spelling and the preceding
modifier change the English security response. Chat delimiters have their own
small responses; opening a conversation is distinct from opening a later turn.
The workspace path and README filename are positive development-work markers.
This intentionally leaves most ordinary lexical variation unexplained.
"""
READS = ()

CHAT_MARKERS = {
    '<think>': 0.17, '</think>': 0.22,
    '<tool_call>': 0.08, '</tool_call>': -0.03,
    '<tool_response>': -0.03, '</tool_response>': -0.18,
    '<|endoftext|>': 0.01,
}
# Each group names a recognizable lexical concept, not token IDs.
LEXICAL_GROUPS = (
    ({'cybersecurity', 'insecurity'}, -0.60),
    ({'safety', 'privacy', 'secure', 'securely', 'securities'}, -0.11),
    ({'sécurité', 'seguridad'}, -0.23),  # French and Spanish security
    ({'防盗', '保安', '售后', '售后服务'}, -0.80),
    ({'安', '安全', '安心', '不安', '安定'}, -0.20),
    ({'公安', '国家安全', '网络安全', '安全感', '保密'}, -0.32),
    ({'神秘'}, -0.54),
    ({'mystery', 'mysterious', 'creepy', 'eerie', 'sinister'}, -0.27),
)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, age, initial_chat = '', 0, False
    else:
        _, previous, age, initial_chat = carry
    text = prefix.token_strings[-1]
    word = text.strip()
    lower = word.lower()
    value = 0.0
    if lower.lstrip('._/-\\') == 'security':
        value = -0.84 if text.startswith(' ') else -0.65
        if word.startswith(('.', '_', '/', '-', '\\')):
            value = -0.77
        if word.isupper():
            value = -0.52
        elif word == 'Security':
            value = -0.81
        modifier = previous.strip().lower()
        if modifier == 'national':
            value = -1.07
        elif modifier == 'social':
            value = -0.22
        elif modifier in {'homeland', 'cyber', 'income', 'food'}:
            value += 0.17
    elif word == 'URITY' and previous.strip() == 'SEC':
        value = -0.38
    elif text == '<|im_start|>':
        value = 0.383 if age == 0 else -0.013
        initial_chat = age == 0
    elif previous == '<|im_start|>' and word == 'user':
        value = 0.091 if initial_chat else -0.023
    elif initial_chat and age == 2 and text == '\n':
        value = -0.104
    elif text == '<|im_end|>':
        value = 0.014 if previous == '</tool_response>' else 0.081
    elif text in CHAT_MARKERS:
        value = CHAT_MARKERS[text]
    elif lower == '/workspace':
        value = 0.17
    elif lower == 'readme':
        value = 0.14
    else:
        for words, response in LEXICAL_GROUPS:
            if lower in words:
                value = response
                break
    return (doc, text, age + 1, initial_chat), value

programs.luna:
"""Mark the security/protection word family, a rare but strong response.

Most observed responses are on "security"; protection words in Chinese also occur.
The final "URITY" token is recognized only after "SEC", for split SECURITY.
"""

READS = ()
SECURITY_WORDS = {"security", "防盗", "保安"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip().strip(".,/<>\"'()[]{}:;_")
    word = token.casefold()
    if word in SECURITY_WORDS:
        return None, -0.82 if word == "security" else -0.79

    if word == "urity" and len(prefix.token_strings) > 1:
        previous = prefix.token_strings[-2].strip().casefold()
        if previous.endswith("sec"):
            return None, -0.45

    return None, 0.0

programs.haiku:
"""Clause-opening conjunctions. A connective that starts a new sentence ('But', 'And', 'So')
drives the component strongly negative; a connective that continues a sentence barely moves it."""
READS = ()

# Activation at a sentence-initial connective (negative: the component fires).
SENTENCE_START = {"but": -5.0, "and": -4.5, "so": -3.0, "yet": -3.0, "or": -2.0, "nor": -1.2,
                  "now": -1.5, "then": -1.1, "moreover": -1.3, "thus": -1.0, "therefore": -0.9,
                  "however": -0.9, "und": -2.5, "но": -3.5, "и": -1.4, "et": -1.3, "aber": -1.0,
                  "pero": -1.2, "しかし": -2.5, "但": -1.2, "而": -1.3}
SENTENCE_END = (".", "!", "?", "\n", '"', "。", "！", "？")
CLAUSE_END = (";", ":", "—", "–", "-", "，", "；")
CLAUSE_SCALE = 0.4      # a connective after a semicolon, dash or comma-like break
MID_BUT = -0.5          # 'but' after an ordinary comma, mid-sentence

def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word not in SENTENCE_START and word != "but":
        return carry, 0.0
    if prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return carry, SENTENCE_START.get(word, 0.0)
    prev = prefix.token_strings[-2]
    if prev.endswith(SENTENCE_END) or "\n" in prev:
        return carry, SENTENCE_START.get(word, 0.0)
    if prev.strip().endswith(CLAUSE_END):
        return carry, CLAUSE_SCALE * SENTENCE_START.get(word, 0.0)
    if word == "but" and prev.strip().endswith(","):
        return carry, MID_BUT
    return carry, 0.0

programs.sol:
"""A lexical amount/extent signal, with a negative response to addition.

'Much' is strongest, especially in 'how much'; 'so', 'too', 'very', and
'pretty' reduce it. 'Many', 'far', and degree/duration words are weaker.
Gradable adjectives fire after degree words like 'how', 'as', or 'too'.
Listed foreign quantity/extent words receive similar positive values;
addition words and stems receive negative ones. A few connecting words
retain a smaller response after a quantity word. Case and word-start spacing
change some responses. Spelling fragments starting 'uch' also fire
(except the code type 'uchar'), as does German 'auch': this is not a purely semantic quantity detector.
All unrecognized tokens receive zero; context resets between documents.
"""

READS = ()

# Approximate quantity words in other languages, not arbitrary token IDs.
LARGE_AMOUNT = {'viel', 'mucho', 'muchos', 'muchas'}
MEDIUM_AMOUNT = {'viele', 'vielen', 'beaucoup', 'mycket', 'veel'}
GRADABLE = {'big', 'large', 'small', 'little', 'high', 'low', 'fast',
            'slow', 'close', 'near', 'hard', 'easy', 'strong', 'weak',
            'young', 'old', 'good', 'bad', 'important', 'difficult'}

OTHER_AMOUNT = {'muito', 'molto', 'çok', 'bardzo', 'banyak', 'nhiều',
                'много', 'многие', 'многих', '많이', '很多', '许多', '不少'}


def response(token, previous):
    text = token.strip()
    word = text.lower()
    capital = text[:1].isupper()
    spaced = token.startswith(' ')
    if word == 'much':
        if previous == 'how':
            return 6.25
        return {'so': 3.45, 'too': 3.7, 'very': 2.85,
                'pretty': 2.15}.get(previous, 5.6 if capital and spaced else 5.1)
    if word == 'many':
        if previous == 'good':
            return 1.15
        if previous in {'in', 'for', 'of', 'on', 'so'}:
            return 1.8
        if previous == 'as':
            return 2.35
        return 2.25 if capital and spaced else (2.05 if spaced else 1.85)
    if word == 'far':
        if capital or not spaced:
            return 1.05
        return {'how': 3.15, 'as': 2.55, 'too': 2.5,
                'so': 1.15, 'a': 1.45}.get(previous, 1.95)
    if word == 'long':
        return {'how': 1.0, 'as': 0.73, 'too': 0.73,
                'so': 0.48, 'very': 0.3}.get(previous, 0.07)
    if word == 'soon':
        return 1.15 if previous in {'as', 'too'} else 0.7
    if word in {'addition', 'additions'}:
        return -1.25 if previous == 'in' else -1.95
    if word == 'additional':
        return -2.5 if capital and spaced else -2.05
    if word == 'additionally':
        return -1.5 if capital else -2.25
    if word == 'uch':
        return 1.9
    # Partial spellings, not complete English words or C's uchar type.
    if not spaced and word.startswith('uch') and word != 'uchar':
        return 0.85
    if word == 'ouch':
        return 1.0
    if word == 'auch':
        return 1.6 if capital else 0.95
    if word in LARGE_AMOUNT:
        return 2.0
    if word in MEDIUM_AMOUNT:
        return 1.3
    if word in {'muit', 'もっと'}:
        return 1.4
    if word == 'дополн':
        return -1.7
    if word == 'добав':
        return -0.7
    if word in OTHER_AMOUNT or word in {'远', '遠', '久'}:
        return 1.0
    if word in {'此外', '额外', '附加', '再加上'}:
        return -1.1
    if word in GRADABLE:
        return {'how': 0.7, 'as': 0.5, 'too': 0.6, 'so': 0.4,
                'very': 0.2, 'pretty': 0.3}.get(previous, 0.0)
    if word == 'often':
        return {'how': 0.62, 'as': 0.72, 'too': 0.77, 'so': 0.56,
                'very': 0.48}.get(previous, 0.28)
    # Quantity phrases extend weakly onto their connecting words.
    if previous == 'much':
        linking = {'of': 1.7, 'as': 0.64, 'more': 0.23,
                   'the': 0.38, 'in': 0.29, 'to': 0.16}
        if word in linking:
            return linking[word]
    if previous == 'many' and word == 'of':
        return 0.46
    if previous == 'far' and word == 'as':
        return 0.3
    if previous == 'addition' and word == 'to':
        return -0.29
    return {'greatly': 1.1, 'considerably': 0.8,
            'amount': 0.22, 'significantly': 0.25}.get(word, 0.0)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = response(token, previous)
    return (doc, token.strip().lower()), value

programs.haiku:
"""Quantity words "much", "many" and "far" switch this component on; "additional" and
"addition" switch it off.

The component responds to the English words for a large amount or extent. "much" is its
strongest trigger, especially in "how much" and "is much" (about 5 to 6), weaker after
"so", "too", "very" or "pretty" (about 2 to 3). "many" gives about 2 in any position, and
"far" about 2 to 3 in "as far as" or "how far". A few foreign or split words for the same
idea (mucho, muito, viel, beaucoup, 很多, 许多, 不少, the "uch" of a split "much") give
about 1 to 2, and "greatly", "considerably", "soon" and German "auch" give about 1. The
word "of" right after "much" or "many" picks up about 1. Generic quantity words ("a lot",
"several", "more", "few") do not fire. "additional" and "additionally" give about -2,
and "addition" about -1.2 in "In addition" and -2 otherwise.
"""
READS = ()

# Words for "much/many" and related degree words, about 1 to 2 each.
AMOUNT = {
    "mucho": 2.1, "muito": 1.2, "muit": 1.3, "viel": 2.0, "vielen": 1.0,
    "beaucoup": 1.7, "greatly": 1.1, "considerably": 0.9, "soon": 0.8,
    "auch": 0.9, "很多": 0.9, "许多": 0.9, "不少": 0.8,
    "uch": 1.7,  # the tail of "much" when the tokenizer splits it
}
NEGATIVE = {
    "additional": -2.2, "additionally": -2.0, "addition": -1.6,
    "额外": -1.3, "дополнительн": -1.8,
}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    before = prefix.token_strings[-2].strip().lower() if len(prefix) > 1 else ""
    if word == "much":
        if before in ("how", "is", "as", "be", "are", "have", "not"):
            return None, 5.5
        if before in ("so", "too", "very", "pretty"):
            return None, 2.8
        return None, 4.6
    if word == "many":
        return None, 2.0
    if word == "far":
        return None, 2.7 if before in ("as", "too", "how") else 2.1
    if word == "addition" and before == "in":
        return None, -1.2
    if word == "of" and before in ("much", "many"):
        return None, 0.9
    if word in AMOUNT:
        return None, AMOUNT[word]
    if word in NEGATIVE:
        return None, NEGATIVE[word]
    return None, 0.0

programs.sol:
"""Token-spelling triggers, dominated by the function abbreviation `func`.

Function words and programming abbreviations trigger more weakly. Independent
branches recognize explicit sex labels and the Cyrillic hard sign. Constants
are approximate training averages; this ignores context and the many small
responses on other words.
"""
READS = ()

# Short names conventionally used in code, rather than arbitrary token IDs.
CODE_NAMES = {
    'fmt': -0.83,       # formatting
    'obj': -1.85,       # object
    'buf': -1.25,       # buffer
    'dest': -0.80,      # destination
    'cond': -0.41,      # condition
    'expr': -0.55,      # expression
    'prob': -0.50,      # probability
}


def response(token):
    word = token.strip().strip('_.$()=/\\\"\'`:-')
    lower = word.lower()
    punctuation = token.lstrip()[:1]

    if lower == 'func':
        if word != 'func':
            return -3.65 if punctuation in '(_' else -4.95
        if punctuation == '_':
            return -5.0
        if punctuation in '(.':
            return -6.25
        return -5.9 if token.startswith('\t') else -7.05
    if lower == 'fn':
        if not word.islower():
            return -0.77
        return -0.8 if punctuation in '._' else -1.18
    if lower in CODE_NAMES:
        value = CODE_NAMES[lower]
        if lower == 'obj' and not word.islower():
            return -0.83
        if lower == 'obj' and punctuation in '(_.)':
            return -1.5
        return value
    if lower == 'fun':
        return -1.95 if word.islower() else -1.55
    if lower == 'unc':
        return -1.7 if token == 'unc' else -0.5
    if lower == 'unct':
        return -0.45
    if lower == 'funct':
        return -1.65
    if 'function' in lower:
        if lower.startswith('dysfunction'):
            return -1.6
        if lower in ('functional', 'functionally'):
            return -1.4
        if lower == 'functioning':
            return -0.6
        if lower.startswith('functionalit'):
            return -0.9
        if lower.startswith('malfunction'):
            return -0.65
        if punctuation in '_=:.':
            return -1.5
        return -0.83 if word.islower() else -1.1
    if lower.endswith('func'):
        return -0.6
    if lower.startswith(('функци', 'ункци', 'funcion')):
        return -1.25
    if lower.startswith(('funció', 'funç', 'funktion')):
        return -0.7
    if lower.startswith('fonction'):
        return -0.4
    if word in ('功能', '的功能'):
        return -1.6
    if word in ('函数', '函'):
        return -0.6

    # Explicit sex labels, not all words denoting people.
    if lower == 'male':
        return -3.08 if token[:1].isspace() else -2.3
    if lower == 'female':
        return -2.1
    if lower in ('males', 'females'):
        return -1.4
    if lower in ('gender', 'genders', 'sexual', 'sexually', 'sexo'):
        return -0.5
    if lower == 'sex':
        return -0.3
    if lower in ('human', 'humans'):
        return -0.4 if word == 'human' else -0.25
    if word == '男':
        return -2.65
    if word in ('男女', '男生'):
        return -2.15
    if word in ('男性', '女生'):
        return -1.7
    if word in ('女性', '女'):
        return -1.1
    if word in ('男人', '男主角'):
        return -0.85
    if token in (' жен', ' муж', ' мужчин'):
        return -0.9
