        value = -0.01
    elif token == '.':
        value = -0.005
    elif s.isascii() and s.isdigit():
        value = -0.006
    elif token == '’s':
        value = 0.048
    elif token == '’t':
        value = 0.06
    elif token == '.com':
        value = -0.08
    elif token.startswith(' ') and s.lower() in (
        'face', 'faces', 'facial', 'cheeks'
    ):
        value = -0.10
    marked = False
    if '¶' in token:
        value = -1.70 if token.startswith(' ') else -2.55
    elif token in MARKED_LETTERS:
        value = MARKED_LETTERS[token]
        marked = True
    elif s in ('脸', '的脸'):
        value = -1.58
    elif s == '臉':
        value = -1.45
    elif s in ('脸颊', '臉頰'):
        value = -0.48
    elif s in ('几乎', '幾乎'):
        value = -0.47
    elif s in ('产业', '產業'):
        value = -0.45
    elif s == '仰':
        value = -0.69
    elif s == 'cả':
        value = -1.38
    elif s in ('<think>', '<tool_call>'):
        value = 0.08
    elif s in ('<|endoftext|>', '<|im_end|>'):
        value = -0.026
    else:
        decomposed = unicodedata.normalize('NFD', s)
        if '\u0309' in decomposed:
            if not token[:1].isspace() and s[:1] in MARKED_LETTERS:
                value = 0.60 * MARKED_LETTERS[s[0]]
                marked = True
            else:
                value = -0.28 if 'a\u0309' in decomposed else -0.10
        elif s and not token[:1].isspace():
            first = unicodedata.normalize('NFD', s[0])
            toned_o = first.startswith('o\u0302') and any(
                t in first for t in '\u0300\u0301\u0303'
            )
            if toned_o:
                value = -0.45 / (len(s) ** 0.7)
            elif (
                len(s) == 1 and '\u0300' in decomposed
                and decomposed[0] in 'ηο'
            ):
                value = -0.55
            elif token in ('ั', 'ื', 'ิ'):
                value = -0.16
            elif token == '้' and previous.endswith('ื'):
                value = -0.48
