    if previous_value < -0.3 and token.isascii() and token.isalpha():
        value += (0.43 / len(token)) * previous_value
    elif '¶' in previous and token.isspace():
        value += 0.19 * previous_value
    next_tail = value if marked or '¶' in token else 0.0
    return (doc, token, next_tail), float(value)

programs.haiku:
"""Layer-0 MLP down-projection component 2222: a token-identity detector for
accented/diacritic letters and a few rare symbols, which it pushes negative.

What it does, in plain terms (the activation is negative on these, near 0 elsewhere):
  * the pilcrow sign ¶ (about -2.5), the strongest and rarest case;
  * the Chinese character for face, 脸 / 臉 (about -1);
  * Latin letters with a hook above (the Vietnamese hỏi tone: ả, ở, ổ, ỉ, ỷ ...), about -0.25;
  * letters with a caron (ě, ǎ, ǒ), about -0.12;
  * any other letter carrying a combining diacritic, about -0.02;
  * everything else, 0.

It reads only the current token's text, so it has no state (carry is passed through).
Its variance explained is small: the component's activation is spread over many
ordinary tokens with no simple concept behind their sign, so these rules capture only
the sharp negative tail.
"""

import unicodedata

READS = ()

PILCROW = "¶"
FACE = "脸臉"
HOOK_ABOVE = "̉"
CARON = "̌"


def marks(text):
    """The combining diacritics in a token's text, after decomposing each letter."""
    return {c for c in unicodedata.normalize("NFD", text) if unicodedata.combining(c)}


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    found = marks(text)
    if PILCROW in text:
        value = -2.5
    elif any(c in FACE for c in text):
        value = -1.0
    elif HOOK_ABOVE in found:
        value = -0.25
    elif CARON in found:
        value = -0.12
    elif found:
        value = -0.02
    else:
        value = 0.0
    return carry, value

