"""Explicit negation and absence, rather than general negative sentiment.

No/none/nothing and null values give positive pulses. Grammatical 'not'
responds chiefly after an auxiliary; 'no' and 'nothing' strengthen after
existence/possession verbs. Some common translations are recognized too.
The remaining lexical and contextual variation is approximated by zero.
"""
READS = ()

EXISTENCE = set('is are was were am be been has have had'.split()) | {"'s", '’s'}
NOT_AFTER = {}
for words, value in (
    ('do does did', .92), ('was were', .82), ('is are am', .64),
    ('has have had', .77), ('can could will would shall should', .60),
    ('may might must need', .40), ("'s ’s", .42),
    ("'m ’m 're ’re also still probably", .60), ('and but to as', 0.0),
):
    NOT_AFTER.update(dict.fromkeys(words.split(), value))

ABSENCE = {}
for words, value in (
    ('null', 1.05), ('nil', 1.25), ('nullptr', 1.8), ('undefined', .88),
    ('nobody', 1.5), ('nowhere nichts rien', 1.85),
    ('neither absence unused unchanged devoid negligible', 1.0),
    ('cannot unable absent rarely anything everything', .65),
    ('impossible nor zero nicht nie', .40),
    ('kein keine нет никогда nunca', 1.25), ('ничего никак', 1.5),
    ('не без', .20), ('nada không tidak', .88),
    ('without non only any true do', -.11),
    ('没有 沒有', 1.9), ('没 沒 无 無 ない なし', 1.6),
    ('未 不要 不会 不會 ません', 1.1), ('不 不是 不能', .4),
    ('无法 無法', .8), ('없 없다 ไม ไม่', 2.0),
    ('毫无 毫無 不存在', 2.2),
):
    ABSENCE.update(dict.fromkeys(words.split(), value))

ROMANCE = set('el la los las de del en que y o para por se es le les'
              ' des du et est pas uma um na nos das e em ao'.split())
ENGLISH = set('the a an and of to is are was were has have had there'
              ' this that with but it he she they we'.split())


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    history = () if carry is None or carry[0] != doc else carry[1]
    raw = prefix.token_strings[-1]
    word = raw.strip()
    bare = word.lstrip('=,([.:_-/')
    low = bare.lower()
    prev = history[-1] if history else ''
    before = history[-2] if len(history) > 1 else ''
    spaced = raw.startswith(' ')
    value = ABSENCE.get(low, 0.0)

    if word in {'not', 'Not'}:
        value = NOT_AFTER.get(prev, -.12) if spaced and word == 'not' else -.14
    elif word in {"'t", '’t'}:
        value = 1.0 if prev in {'don', 'doesn', 'didn', 'haven', 'hasn', 'wasn'} else .8
        if prev not in {'don', 'doesn', 'didn', 'haven', 'hasn', 'wasn', 'can',
                        'won', 'wouldn', 'shouldn', 'aren', 'couldn', 'isn',
                        'weren', 'hadn', 'ain', 'n'}:
            value = 0.0
    elif low == 'no':
        value = 1.23 if spaced else .60
        if bare != word:
            value = .8 if word.startswith('_') else 1.4
        if bare != 'no':
            value = .60 if bare == 'NO' else .90 if spaced else .80
        elif prev in EXISTENCE:
            value = 2.0 + (.30 if before == 'there' else 0.0)
        elif prev in {'with', 'make', 'makes', 'contains', 'absolutely'}:
            value = 1.75
        elif prev in {',', '.', 'so', '→'}:
            value = .96
        if bare == 'no' and sum(w in ROMANCE for w in history) >= 2:
            if not any(w in ENGLISH for w in history):
                value = .20  # Spanish/Portuguese 'no' is weaker than English.
    elif low == 'nothing':
        value = 3.12 if bare == 'nothing' and spaced else 2.90
        if bare == 'nothing' and not spaced:
            value = 2.60
        elif spaced and bare == 'nothing' and prev in EXISTENCE:
            value = 3.85 + (.30 if before == 'there' else 0.0)
    elif low == 'none':
        value = 1.95 if bare == 'None' else 2.20
        if bare != word:
            value -= .15
    elif low == 'never':
        value = 1.60 if bare == 'never' and spaced else 1.25
    elif low in {'не', 'нет', 'rien'} and not spaced:
        value = .10 if low != 'rien' else .55
    elif '没有' in word or '沒有' in word:
        value = 1.9
    elif '没' in word or '沒' in word:
        value = 1.8
    elif word.endswith('ありません'):
        value = 2.0
    elif word.endswith(('ない', 'いません')):
        value = 1.6
        if word in {'少ない', 'できない', 'らない', 'えない'}:
            value = .7
    elif word in {'لا', 'بدون'}:
        value = .90 if spaced else .20

    return (doc, (history + (word.lower(),))[-8:]), float(value)

