"""A lexical place/placement detector with one-token phrase memory.

Large negative responses mark 'place' and its inflections. They weaken in
occurrence ('take place') and precision ('decimal places') expressions;
'place of' also fires on 'of'. A small related-word/translation lexicon
gets weaker responses. Unlisted tokens get zero, not a semantic guess.
"""
READS = ()
PLACE = {'place': -6.4, 'places': -6.1, 'placed': -4.4,
         'placing': -5.1, 'placement': -3.0, 'placements': -3.0}
TAKE = frozenset(('take', 'takes', 'took', 'taking', 'taken'))
REPLACE = frozenset(('replace', 'replaces', 'replaced', 'replacing',
                     'replacement', 'replacements'))
# Each group names an ordinary word family or a shared meaning.
GROUPS = (
    (-1.2, 'put puts putting 放 放在 放到 放入 摆放'),
    (-0.9, 'location locations'),
    (-0.9, 'people'),
    (-1.1, 'things'),
    (-1.0, 'plant plants'),
    (-1.7, 'workplace workplaces placeholder placeholders'),
    (-3.1, 'inplace 放置'),
    (-2.4, 'plac'),
    (-2.2, 'placebo'),  # A spelling relative, not a place synonym.
    (-2.3, 'мест место места месте lugar lugares 地方 场所'),
    (-1.7, 'platz plätze plaats 的地方'),
    (-0.9, 'lieu'),
)
RELATED = {word: value for value, words in GROUPS for word in words.split()}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = '' if carry is None or carry[0] != doc else carry[1]
    raw = prefix.token_strings[-1]
    bare = raw.strip()
    word = bare.lstrip('._-/').lower()
    value = RELATED.get(word, 0.0)
    if word in PLACE:
        value = PLACE[word] - (0.3 if bare[:1].isupper() else 0.0)
        if word == 'place' and previous in TAKE:
            value = -4.3 if previous in ('taken', 'taking') else -3.65
        elif word == 'place' and previous == 'in':
            value = -5.15
        elif word == 'place' and previous == '|':
            value = -7.3  # A tabular field, such as '| place of birth'.
        elif word == 'places' and previous == 'decimal':
            value = -3.1
        elif not raw[:1].isspace():
            if previous == 're':
                value *= 0.08 if word.startswith('placement') else 0.25
            elif previous == 'dis':
                value = -0.25 if word.startswith('placement') else -2.2
            elif raw == 'placement':
                value = -1.7
    elif word in ('aces', 'aced', 'acing'):
        value = -0.5 if word == 'aces' else -0.9
        if previous == 'pl' and not raw[:1].isspace():
            value = -5.5  # Join PL + ACES, Pl + acing, etc.
            word = {'aces': 'places', 'aced': 'placed', 'acing': 'placing'}[word]
    elif word in REPLACE:
        value = -1.15 if raw.startswith('_') else -0.55
    if word == 'of':
        if previous in ('place', 'places'):
            value = -2.9
        elif previous in ('placement', 'placements'):
            value = -1.8
    return (doc, word), value

