"""A digit-boundary feature: respond to what comes immediately after a number.

Bare separators and attached single letters produce negative activations.
Longer attached alphabetic pieces tend to produce positive activations instead.
Dates, ordinal suffixes, and code after tab-separated line numbers have their
own recognizable forms. Separators respond more strongly after multi-digit
numbers than after a single digit. Tokens containing trailing whitespace are
not bare number separators. Tests use the newest token and reset at document
edges. These are fitted behavioral estimates, not an internal model simulation.
"""

READS = ()

SEPARATORS = {
    '.': (-0.76, -0.89), ',': (-0.58, -0.84),
    ':': (-1.06, -1.52), '/': (-0.60, -0.93),
    '-': (-0.74, -0.97), '–': (-0.46, -0.46),
    '_': (-1.42, -1.42),
}
ORDINAL_ENDINGS = {'st': -0.20, 'nd': -0.05, 'rd': 0.13, 'th': -1.05}
DATE_UNITS = {
    '年': -0.84, '月': -1.74, '日': -1.64,
    '년': -1.07, '월': -1.18, '일': -0.96,
}


def after_digit(token, digits=1):
    if token in SEPARATORS:
        return SEPARATORS[token][digits > 1]
    if token in ORDINAL_ENDINGS:
        return ORDINAL_ENDINGS[token]
    if token in DATE_UNITS:
        return DATE_UNITS[token]
    if token == ' ':
        return -0.36
    if len(token) == 1 and token.isascii() and token.isalpha():
        if token.lower() == 'd':  # dimensional notation such as 2D and 3d
            return -1.90
        if token.lower() in 'abcef':  # other hexadecimal letters
            return -1.38
        if token.lower() == 's':  # seconds or plural numeric decades
            return -1.14
        if token == 'x':  # multiplication and hexadecimal prefixes
            return -1.09
        return -0.76
    if token in {'号', '集', '路', 'つの'}:  # numbered items and counters
        return -0.93
    if token.isascii() and token.isalpha():
        if token == 'px':
            return -0.28
        return 0.55
    word = token.strip()
    if token.startswith('\t') and word.isascii() and word.isalpha():
        if word in {'import', 'from', 'export'}:
            return 0.94
        return 0.48
    if word.isascii() and word.isalpha() and token != word:
        if token in {' AM', ' PM'}:
            return -0.39
        return -0.10 if len(word) == 1 else 0.11
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    digits = carry[1] if carry is not None and carry[0] == doc else 0
    value = after_digit(token, digits) if digits else 0.0
    if token.isdigit():
        digits += len(token)
    else:
        digits = 0
        for char in reversed(token):
            if not char.isdigit():
                break
            digits += 1
    return (doc, digits), float(value)

