"""Activation of layers.0.mlp.down_proj:2229.

The component reads the token written directly after a number, with no space in between.
When that token is a separator or a unit that attaches to digits, it goes negative:
  - the time colon in "09:12" is the strongest (about -1.3);
  - letter and date units right after digits, such as "2d", "5x", "3s", "7th", "3a",
    and the CJK date marks 月, 日, 年 (about -1.2 to -1.8), are strong;
  - the decimal point, thousands comma, hyphen and slash ("0.001", "3,000", "2024-01",
    "1/2") are milder (about -0.8).
Anything else, including digits themselves, spaces and words after spaces, stays near 0.
So it is a "number-continuation" detector: it marks the punctuation or unit that
continues a number, and does not fire on the digits of the number.
"""

READS = ()

DIGITS = set("0123456789")
SEPARATOR = set(".,-/")     # decimal point, thousands comma, hyphen, slash
TIME_COLON = ":"
UNITS = {"th", "月", "日", "年"}


def _is_digit(s):
    return s != "" and all(c in DIGITS for c in s)


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    if len(toks) < 2 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return carry, 0.0
    prev, cur = toks[-2], toks[-1]
    if not _is_digit(prev):
        return carry, 0.0
    if cur == TIME_COLON:
        return carry, -1.3
    if cur in SEPARATOR:
        return carry, -0.8
    if cur in UNITS or (len(cur) == 1 and cur.isalpha()):
        return carry, -1.4
    return carry, 0.0

