def char_value(text):
    """Largest value of any Chinese money-related character in the token."""
    best = 0.0
    for ch in text:
        if ch in GOODS_CHARS:
            best = max(best, GOODS_VALUE)
        elif ch in CURRENCY_CHARS:
            best = max(best, VALUE["currency"])
        elif ch in MONEY_CHARS:
            best = max(best, VALUE["money"])
    return best


def word_value(token):
    """Value of a whole English or Russian word, ignoring case, spaces and underscores."""
    word = token.strip(" _-.(\t\n").lower()
    if word == "goods":
        return 1.5
    if word in CURRENCY:
        return VALUE["currency"]
    if word in MONEY:
        return VALUE["money"]
    if word in TRADE:
        return VALUE["trade"]
    if word in FINANCE:
        return VALUE["finance"]
    return 0.0


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    return carry, float(max(word_value(token), char_value(token)))

