"""Negative-polarity "any" / "ever" and existential 有.

Layer-0 MLP component layers.0.mlp.down_proj:2231 is mostly silent. Its one clear job is
on the word "any" (and "ever", "seen") in negative-polarity or question contexts, where it
swings negative: "if you have any questions", "have you ever", "never seen any", "there are
any". The same sign shows for the Chinese existential 有 ("there is/are") and 任何 ("any").
Elsewhere it stays near zero, with small token-specific wiggles this program does not model.

The program predicts, at each token:
  - " any" after have/has/had: strongly negative;
  - " any" after if/or/are/there/never/ever/etc.: mildly negative;
  - " ever" / " seen" after have/has/never/haven't: mildly negative;
  - 有 / 任何 / 有人 / 有的 / 还有: mildly negative;
  - anything else: 0.
"""

READS = ()

HAVE = {" have", " has", " had", " Have", " Has"}
CUE = {" if", " If", " or", " are", " there", " never", " ever", " not", " no", " haven", "n't", " Have"}
PERFECT = {" have", " has", " had", " never", " haven", " ever", "'ve", " Have", " seen"}
EXIST_ZH = {"有", "有人", "有的", "有一", "任何", "还有", "看到", "见过"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix) > 1 else ""
    if tok == " any":
        if prev in HAVE:
            return carry, -0.8
        if prev in CUE:
            return carry, -0.3
        return carry, 0.0
    if tok in (" ever", " seen") and prev in PERFECT:
        return carry, -0.4
    if tok in EXIST_ZH:
        return carry, -0.3
    return carry, 0.0

