programs.sol:
"""Zero as a new number versus zero continuing a number.

Leading zero is usually positive; after a nonzero digit it is negative.
Runs of zeros have weaker negative responses. Separators, digit-run length,
indented numeric lines, and surrounding character classes adjust strength.
Fullwidth digits are treated like ASCII digits. All other tokens get zero.
Only the last 80 characters of the current document are remembered.
"""
import re

READS = ()
FULLWIDTH = str.maketrans('０１２３４５６７８９', '0123456789')


def zero_response(before):
    if not before:
        return 0.182
    last = before[-1]
    if last == '0':
        run = len(before) - len(before.rstrip('0'))
        first = before[-run-1:-run]
        if first.isdigit():
            return -0.59 / run ** 0.6
        if run == 1:
            return -0.04 if first == ',' else -0.20
        return -0.37 / (run - 1) ** 0.45
    if last in '123456789':
        run = re.search(r'\d+$', before)[0]
        value = -1.16 - (0.23 if len(run) == 2 else 0.0)
        line = before.rsplit('\n', 1)[-1]
        if '\n' in before and line.strip().isdigit():
            value -= 0.25
        return value
    if last.isspace():
        prior = before[-2:-1] if last == ' ' else ''
        if prior.isdigit():
            return 0.93 if prior == '0' else 0.67
        return 1.64 if prior.isalpha() else 1.52
    if last in '.,':
        follows_digit = before[-2:-1].isdigit()
        if last == '.':
            return 0.18 if follows_digit else 0.80
        return 0.66 if follows_digit else 1.04
    if last == ':':
        return 1.00
    if last in '[({<':
        return 1.60
    # Hexadecimal letter endings give a smaller positive response.
    if last in 'abcdef':
        return 0.58
    if last.isalpha():
        return 1.80 if ord(last) >= 0x3000 else 1.08
    return 1.38


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1].translate(FULLWIDTH)
    value = zero_response(before) if token == '0' else 0.0
    return (doc, (before + token)[-80:]), float(value)

"""Negative lexical feature for open-ended lists and alternatives.

'Etc.', Chinese 等, Japanese など, and Korean 등 are strongest. 'Other',
'another', and equality words are weaker. Reciprocal phrases are attenuated.
Chinese 等 also fires in its waiting/rank/equality senses, at different sizes.
Everything else gets a near-zero prediction; weak unrelated responses are omitted.
"""
READS = ()

# Fused list continuations and related expressions, grouped by language.
LIST_MARKERS = {
    '等等': -9.5, '之类': -4.2, '之类的': -4.2,
    'など': -8.15, 'などの': -6.05, 'などで': -3.45,
    'などが': -4.8, 'などを': -4.8,
    'といった': -3.06, 'とか': -1.67,
    'なんか': -1.6, 'なんて': -1.6, 'や': -0.41, 'ら': -0.79,
    '등의': -6.3, '등을': -6.3, '같은': -1.35,
    'gibi': -2.3, 'وغيرها': -3.5,
}
CHINESE_COMPOUNDS = {
    '等待': -2.1, '等候': -1.3, '等着': -4.0, '等到': -5.6,
    '等于': -1.0, '平等': -5.0, '同等': -5.0,
    '高等': -8.0, '等级': -3.5,
}
ALTERNATIVES = {
    '其他': -0.85, '另一': -0.85, '或其他': -1.8, '和其他': -1.8,
    '以及其他': -2.65, '这些': -0.63, '以及': -0.63,
}


def response(token, previous):
    word = token.strip()
    lower = word.lower()
    if word == '等':
        if previous.endswith('相'):  # 相等: equal to one another.
            return -4.8
        if previous.endswith(('不', '何')):
            return -8.2
        if previous.endswith('恒'):
            return -9.2
        return -11.65
    if word in CHINESE_COMPOUNDS:
        return CHINESE_COMPOUNDS[word]
    if word in LIST_MARKERS:
        return LIST_MARKERS[word]
    if word.startswith('等'):
        return -6.25
    if word.startswith('など'):
        return -4.8
    if word == '등':
        return -9.3 if token.startswith(' ') else -8.3
    if lower == 'etc':
        return -5.25 if token.startswith(' ') else -3.6
    if lower in {'other', '(other'}:
        if previous == 'each':
            return -0.125
        if previous == 'the':
            return -0.51
        if previous in {'any', 'some', 'many', 'all', 'no'}:
            return -0.78
        return -0.7 if word == 'other' and not token.startswith(' ') else -0.99
    if lower == 'another':
        return -0.39 if previous == 'one' else -1.02
    if lower in {'equal', '.equal', 'equality', 'inequality', 'unequal'}:
        return -1.06
    if lower in {'equally', 'inequalities'}:
        return -0.67
    if lower in {'equivalent', 'equivalence'}:
        return -0.43
    if lower == 'respectively':
        return -0.5
    return ALTERNATIVES.get(word, -0.001)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = response(token, previous)
    # Recognize 等 even when its UTF-8 bytes were split between tokens.
    if '�' in token and prefix.text_prefixes[-1].endswith('等'):
        value = -12.85
    return (doc, token.strip().lower()), float(value)

