"""Mid-word consonant fragments (layers.0.mlp.down_proj, component 2234).

What it does: this component reads a token that continues a word which the
tokenizer has split into pieces: a piece with no leading space, made only of
lowercase letters, and containing no vowel (e.g. the "ν" in a Greek word, the
"ž" or "č" in Czech, "v" or "h" in a Latin word). It answers with a positive
activation for those pieces, largest for Greek letters, then Cyrillic, then Latin,
and close to zero for everything else: whole words (which start with a space), capitals,
digits, punctuation, and pieces that contain a vowel.

The rule is per token and needs no context, so it carries no state.
It explains only a small share of the variance (about 6% on eval): most of the
component is specific to individual tokens, which a short rule cannot list.
"""
import unicodedata

# Letters that count as vowels (Latin, Greek, Cyrillic, and common accented ones).
VOWELS = set("aeiouyáéíóúýěůàèìòùâêîôûäëïöüãõåœαεηιοωυάέήίόύώаеёиоуыэюяəıőű")

# Typical activation for a consonant-only piece, by the script of its letters.
SCALE = {"GREEK": 0.30, "CYRILLIC": 0.13, "LATIN": 0.07}


def _script(token):
    name = unicodedata.name(token[0], "")
    for script in SCALE:
        if name.startswith(script):
            return script
    return None


def _value(token):
    if not token or token[0].isspace() or not token.isalpha():
        return 0.0  # whole words, digits, punctuation, byte fragments
    if token != token.lower():
        return 0.0  # capitals sit near zero
    if any(ch in VOWELS for ch in token):
        return 0.0  # pieces with a vowel sit near zero
    return SCALE.get(_script(token), 0.0)


READS = ()


def step(carry, prefix, upstream):
    """Activation at the newest token: a consonant-only word-internal piece."""
    return carry, float(_value(prefix.token_strings[prefix.position]))

