def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    names = script_names(token)
    value = 0.002

    if any("GREEK" in name for name in names):
        value += 0.099
    elif any("CYRILLIC" in name for name in names):
        value += 0.013
    elif any("HANGUL" in name for name in names):
        value += 0.020
    elif any("CJK" in name for name in names):
        value += 0.002
    elif any("HIRAGANA" in name for name in names):
        value += 0.004
    elif any("THAI" in name for name in names):
        value -= 0.018
    elif any("ARABIC" in name for name in names):
        value -= 0.006

    # A few Latin letters and non-ASCII continuation context are mild cues.
    lower = token.lower()
