    previous = '' if first else carry[1]
    raw = prefix.token_strings[-1]
    word = raw.strip().lower()
    value = 0.0
    if first and raw and set(raw) == {'#'} and len(raw) <= 4:
        value = HEADING_LEVELS[len(raw)]
    elif raw.startswith(' '):
        value = ATTENUATING_ADVERBS.get(word, 0.0)
        if word == 'example' and previous == 'for':
            value = -.115
        elif word == 'known' and previous in {'also', 'well'}:
            value = .15 if previous == 'also' else .105
        elif word == 'source':
