INSTRUMENTS = {'tool', 'tools', 'method', 'methods', 'function'}
PRONOUNS = {'you', 'me', 'him', 'her', 'us', 'them', 'it'}
REQUEST = {'ask', 'asks', 'asked', 'asking'}
GUIDANCE = {'want', 'wants', 'wanted', 'need', 'needs',
            'require', 'requires', 'required', 'help', 'helps', 'helped'}
