                decay = 0.45 if word == 'used' else \
                    (0.72 if current == 'to' else 0.55)
                value = max(value, use_value(word, current) * decay ** distance)
                break
            if word in TRY and current == 'to':
                value = max(value, TRY[word] * 0.45 ** distance)
                break
        if current == 'to' and len(words) > 1 and previous in PRONOUNS:
            verb = words[-2]
            extra = 0.80 if verb == 'for' else \
                0.90 if verb in REQUEST else 0.60 if verb in GUIDANCE else 0.0
            value = max(value, extra)
    if current in FOREIGN_FOR:
        value = -0.34
    if not tail and current == 'for':
        value = 0.79 if token.startswith(' ') else 0.55
    if '\ufffd' in token and prefix.text_prefixes[-1].endswith('♂'):
        value = -1.97
    return (doc, (tail + token)[-100:]), float(value)

programs.haiku:
"""Purpose 'to' / 'for'.

The component fires on the word "to" (or "for") when the word just before it sets up a
purpose or a means: "used to", "trying to", "try to", "attempt to", "use ... to".
It fires weaker when the word before says something is needed or difficult
("needed to", "hard to", "designed to"). Everywhere else it stays near zero.
"""

READS = ()

# Words that name an aim, an attempt or a use. "used to" and "trying to" are the strongest.
AIM_WORDS = {
    "used": 2.8, "trying": 3.0, "tried": 2.5, "try": 2.1, "tries": 2.1,
    "attempt": 1.7, "attempts": 1.7, "use": 1.7, "uses": 1.7, "using": 1.5,
}

# Words that say something is needed, hard, designed or useful for a purpose.
NEED_WORDS = {
    "needed": 0.8, "need": 0.7, "required": 0.8, "designed": 0.7, "hard": 0.7,
    "difficult": 0.7, "wanted": 0.6, "want": 0.6, "useful": 1.6, "important": 0.7,
    "effort": 0.8, "efforts": 0.9, "tool": 0.8, "asked": 0.6, "worked": 1.0,
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip()
    if token not in ("to", "for") or len(prefix) < 2:
        return carry, 0.0
    before = prefix.token_strings[-2].strip().lower()
    if before in AIM_WORDS:
        return carry, AIM_WORDS[before]
    return carry, NEED_WORDS.get(before, 0.0)

"""Negative spikes on the connective that opens a conclusion or consequence.

"Therefore", "thus", "hence" (also when the word is split across tokens) and "因此"
open a conclusion and push the component's activation to about -6 to -7. A bare "so"
(or "所以", "ですから") does the same more weakly, about -3.5, when it opens a clause:
after a comma, a full stop or a line break, or starts the text. Inside a clause
("an operator so that ...") it is only about -1.5. Everywhere else the activation is
near zero."""

READS = ()

STRONG = ("therefore", "thus", "hence", "因此")
SO_WORDS = ("so", "所以", "ですから")
CLAUSE_END = tuple(",，.。;；:\n!?！？")


def ends_word(text, word):
    """True if the decoded text ends with `word` as a whole word (not inside a longer one)."""
    if not text.lower().endswith(word):
        return False
    before = text[: len(text) - len(word)]
    return not (before and before[-1].isascii() and before[-1].isalpha())


def step(carry, prefix, upstream):
    text = prefix.text_prefixes[-1]
    for word in STRONG:
        if ends_word(text, word):
            return carry, -6.0
    for word in SO_WORDS:
        if ends_word(text, word):
            before = text[: len(text) - len(word)].rstrip(" ")
            if not before or before.endswith(CLAUSE_END):
                return carry, -3.5
            return carry, -1.5
    return carry, 0.0

programs.luna:
"""Estimate the component from explicit consequence and inference connectives."""

READS = ()

# These are recognizable equivalents of "therefore" or "hence", not token IDs.
INFERENCE_CONNECTIVES = frozenset({
    "therefore", "hence", "thus", "consequently", "accordingly",
    "因此", "所以", "故", "ので", "なので", "ですから", "므로",
    "donc", "thereby", "portanto",
})


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip()
    word = token.casefold()

    # Some byte-pair tokens split a word like "Hence" or "portanto" in two.
    if len(prefix.token_strings) > 1:
        same_document = prefix.document_ids[-2] == prefix.document_ids[-1]
        if same_document:
            for pieces in (2, 3):
                if len(prefix.token_strings) < pieces:
                    continue
                if any(
                    doc != prefix.document_ids[-1]
                    for doc in prefix.document_ids[-pieces:]
                ):
                    continue
                joined = "".join(prefix.token_strings[-pieces:]).strip()
                if joined.casefold() in INFERENCE_CONNECTIVES:
                    token = joined
                    word = joined.casefold()
                    break

    if word == "so":
        # Sentence-initial, capitalized "So" is more consistently inferential.
        return None, -3.5 if token[:1].isupper() else -1.9

    if word not in INFERENCE_CONNECTIVES:
        return None, 0.0

    # Capitals and lowercase forms have different average activations, while
    # still expressing the same kind of connective.
    if word == "hence":
        return None, -7.5 if token[:1].isupper() else -6.9
    if word in {"therefore", "thus"}:
        if token[:1].isupper():
            return None, -6.5 if word == "therefore" else -6.1
        return None, -4.2 if word == "therefore" else -4.6
    if word in {"因此", "所以", "故", "ので", "므로"}:
        return None, -6.0
    if word == "なので":
        return None, -4.2
    if word in {"ですから", "consequently", "accordingly", "donc"}:
        return None, -2.6
    if word == "portanto":
        return None, -1.3
    return None, -1.6

programs.haiku:
"""Layer-0 MLP down_proj, component 2238.

What it does: it goes negative on the vocabulary of online-gambling and casino spam,
mostly written in Chinese, and on the website words that travel with it. Its
activation is about zero on ordinary text. The Chinese gambling and "official site /
entertainment city" words are the strongest; generic web words are weaker.

Each token is matched whole (spaces stripped, lowercased), so a word fires only as a
word. Levels are the average activation on each group in training text. Chat/tool
markup (<tool_call>, </tool_call>, <tool_response>, </think>) is also negative.
Every other token predicts 0.
"""

READS = ()

TOP_SPAM = {"网址", "官网", "娱乐", "娱乐城", "网站", "開户", "开户", "开奖", "彩票", "博彩", "澳门", "赌场", "赌"}
CN_GAMBLING = {"老虎机", "棋牌", "网投", "外围", "足球", "皇冠", "体育投注", "赌球", "投注", "分彩", "时时彩"}
CN_WEB = {"在线", "平台", "下载", "注册", "登录", "论坛", "直播", "影院", "新开", "传奇", "私服", "国际", "体育", "官方", "游戏", "网", "网页", "网上", "线上", "视频", "观看", "播放", "免费"}
EN_WEB = {"casino", "gambling", "online", "website", "site", "sites", "app", "games"}
DOMAIN = {".com", ".org", ".net"}
MARKUP = {"<tool_response>": -1.0, "<tool_call>": -0.6, "</tool_call>": -0.7, "</think>": -0.8}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token in MARKUP:
        return carry, MARKUP[token]
    word = token.strip().lower()
    if word in TOP_SPAM:
        return carry, -3.0
    if word in CN_GAMBLING:
        return carry, -2.0
    if word in CN_WEB:
        return carry, -1.4
    if word in EN_WEB or word in DOMAIN:
        return carry, -0.5
    return carry, 0.0

