programs.sol:
"""Negative activation for the word 'return', in code or ordinary prose.

Inflections and capitalization keep most of the signal.  Its strength also
varies with the whitespace or identifier punctuation packaged in the token.
Common return/back translations, reply/output words, and the fragment 'ret'
receive weaker signals.  A small echo marks articles and prepositions directly
after return words.  Other tokens receive zero.  Document boundaries stop the echo.
"""
READS = ()

# Return/reply/recurrence characters and common translations of return or reply.
BACK_WORDS = {
    '回': -4.1, '迴': -3.7, '返回': -3.6,
    '回来': -2.6, '回家': -2.6, '回去': -2.6, '回国': -2.6,
    '回报': -2.6, '归来': -2.6,
    '回到': -1.8, '收回': -1.8, '退回': -1.8,
    '返': -1.7, '帰': -1.7, '归': -1.4, '歸': -1.4,
    '回答': -1.2, '的回答': -1.2, '回复': -1.2, '回应': -1.7,
    '还': -0.6, '還': -0.7, '退': -1.2, '회': -1.9,
    'zurück': -1.5, 'terug': -1.7, 'trả': -2.0, 'ответ': -0.8,
    '回收': -1.8, '回归': -1.4, '回到了': -1.4, '回头': -1.2,
}


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    text = raw.strip()
    word = text.lstrip('.@_)-')
    lower = word.lower()
    punctuation = word != text
    split_back = '\ufffd' in raw and raw.endswith('回')
    if (raw == '\ufffd' and len(prefix.token_strings) > 1
            and prefix.document_ids[-1] == prefix.document_ids[-2]):
        split_back = prefix.text_prefixes[-1].endswith('回')
    if split_back:
        value = -6.0  # The return character completed across byte tokens.
    elif lower == 'return':
        if punctuation:
            value = -3.8 if text.startswith('_') else -4.5
        elif word.isupper():
            value = -4.8
        elif word == 'Return':
            value = -5.6 if raw.startswith(' ') else -5.25
            if raw.startswith('\t'):
                value = -4.55
        else:
            value = -5.85
            if raw.startswith(' '):
                value = -5.53
            elif raw.startswith('\t'):
                value = -6.13
    elif lower in {'returns', 'returned', 'returning'}:
        value = -4.4
        if lower == 'returns':
            value = -4.7 if word[0].isupper() else -4.5
        elif lower == 'returned':
            value = -4.3
        if punctuation:
            value = -3.6
    elif lower.startswith('return'):
        value = -2.4  # 'return' embedded in a longer identifier
    elif lower == 'ret':
        value = -1.4 if raw[:1].isspace() or punctuation else -0.9
    elif lower.startswith('retorn'):
        value = -2.9  # Romance-language return stem
    elif lower.startswith('retour'):
        value = -2.0  # French return stem
    elif 'озвращ' in lower:
        value = -3.7  # Russian return stem
    elif text in BACK_WORDS:
        value = BACK_WORDS[text]
    elif lower in {'reply', 'replied', 'replies'}:
        value = -1.0
    elif lower in {'yield', 'yields'}:
        value = -0.9 if lower == 'yield' else -0.65
    elif lower in {'callback', 'callbacks', 'echo'}:
        value = -0.7
    elif lower.startswith(('retina', 'retro')):
        value = -1.0  # Spelling resemblance, not a shared meaning.
    elif lower.startswith(('retir', 'retriev', 'retention', 'retain')):
        value = -0.6
    elif lower in {'response', 'responses', 'respond', 'responded',
                   'responding', 'output', 'outputs', 'outcome', 'outcomes'}:
        value = -0.25
    else:
        value = 0.0
    # In phrases such as 'return of' and 'returns the', the next function
    # word keeps a small trace of the return signal.
    if (len(prefix.token_strings) > 1
            and prefix.document_ids[-1] == prefix.document_ids[-2]):
        previous = prefix.token_strings[-2].strip().lower()
        if previous in {'return', 'returns', 'returned', 'returning'}:
            value += {'of': -1.0, 'to': -0.2, 'the': -0.52,
                      'a': -0.4, 'an': -0.54}.get(text.lower(), 0.0)
    return None, value

